package io.huze.glamourer;

import static io.huze.glamourer.Config.GROUP;
import io.huze.glamourer.color.ColorGroupSettings;
import io.huze.glamourer.glam.IconScale;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GROUP)
public interface Config extends net.runelite.client.config.Config
{
	String GROUP = "glamourer";

	String KEY_NAV_PRIORITY = "navPriority";

	@ConfigItem(
		keyName = KEY_NAV_PRIORITY,
		name = "Navigation Bar Priority",
		description = "Adjusts the order in the nav bar."
	)
	default int navPriority()
	{
		return 10;
	}

	String KEY_HIDE_SIDEBAR_ICON = "hideSidebarIcon";

	@ConfigItem(
		keyName = KEY_HIDE_SIDEBAR_ICON,
		name = "Hide Sidebar Icon",
		description = "Remove the Glamourer button from the sidebar. Glamours stay active."
	)
	default boolean hideSidebarIcon()
	{
		return false;
	}

	String KEY_ICON_SCALE = "iconScale";

	@ConfigItem(
		keyName = KEY_ICON_SCALE,
		name = "Icon Scale",
		description = "Scale of item icons in the panel."
	)
	default IconScale iconScale()
	{
		return IconScale.PERCENT_100;
	}

	String KEY_SHADE_INTENSITY = "shadeIntensity";

	@ConfigItem(
		keyName = KEY_SHADE_INTENSITY,
		name = "Shade Intensity",
		description = "How much of the game's lighting the item viewer and color swatches show, from none to all of it."
	)
	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	default int shadeIntensity()
	{
		return 100;
	}

	// --- Party Sync Section ---

	@ConfigSection(
		name = "Party Sync",
		description = "Glamour synchronization for party members",
		position = 3
	)
	String SECTION_PARTY_SYNC = "sectionPartySync";

	String KEY_PARTY_SYNC_SEND = "partySyncSend";
	String NAME_PARTY_SYNC_SEND = "Sync your appearance";
	String DESC_PARTY_SYNC_SEND = "Send your glamours to others in the same RuneLite party.";
	@ConfigItem(
		keyName = KEY_PARTY_SYNC_SEND,
		name = NAME_PARTY_SYNC_SEND,
		description = DESC_PARTY_SYNC_SEND,
		section = SECTION_PARTY_SYNC
	)
	default boolean partySyncSend()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_PARTY_SYNC_SEND,
		name = "",
		description = "",
		section = SECTION_PARTY_SYNC
	)
	void setPartySyncSend(boolean sync);

	String KEY_PARTY_SYNC_RECV = "partySyncReceive";
	String NAME_PARTY_SYNC_RECV = "Sync others' appearances";
	String DESC_PARTY_SYNC_RECV = "Apply glamours received from others in the same RuneLite party.";
	@ConfigItem(
		keyName = KEY_PARTY_SYNC_RECV,
		name = NAME_PARTY_SYNC_RECV,
		description = DESC_PARTY_SYNC_RECV,
		section = SECTION_PARTY_SYNC
	)
	default boolean partySyncReceive()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_PARTY_SYNC_RECV,
		name = "",
		description = "",
		section = SECTION_PARTY_SYNC
	)
	void setPartySyncReceive(boolean sync);

	String KEY_PARTY_SYNC_PROMPTED = "partySyncPrompted";
	@ConfigItem(
		keyName = KEY_PARTY_SYNC_PROMPTED,
		name = "",
		description = "",
		hidden = true
	)
	default boolean partySyncPrompted()
	{
		return false;
	}
	@ConfigItem(
		keyName = KEY_PARTY_SYNC_PROMPTED,
		name = "",
		description = "",
		hidden = true
	)
	void setPartySyncPrompted(boolean prompted);

	// --- Advanced Section ---

	@ConfigSection(
		name = "Advanced options",
		description = "Power user / developer options",
		position = 4,
		closedByDefault = true
	)
	String SECTION_ADVANCED = "sectionAdvancedOptions";

	String KEY_EXPANDED_RIGHT_CLICK = "advancedOptions";

	@ConfigItem(
		keyName = KEY_EXPANDED_RIGHT_CLICK,
		name = "Expanded Right Click Options",
		description = "Show advanced options in menus.",
		section = SECTION_ADVANCED
	)
	default boolean expandedRightClick()
	{
		return false;
	}

	// --- Hidden ---

	String KEY_GLAMOUR_WINDOW_WIDTH = "glamourWindowWidth";
	@ConfigItem(
		keyName = KEY_GLAMOUR_WINDOW_WIDTH,
		name = "",
		description = "",
		hidden = true
	)
	default int glamourWindowWidth()
	{
		return 680;
	}

	String KEY_GLAMOUR_WINDOW_HEIGHT = "glamourWindowHeight";
	@ConfigItem(
		keyName = KEY_GLAMOUR_WINDOW_HEIGHT,
		name = "",
		description = "",
		hidden = true
	)
	default int glamourWindowHeight()
	{
		return 420;
	}

	String KEY_GLAMOUR_WINDOW_COLORS_WIDTH = "glamourWindowColorsWidth";
	@ConfigItem(
		keyName = KEY_GLAMOUR_WINDOW_COLORS_WIDTH,
		name = "",
		description = "",
		hidden = true
	)
	default int glamourWindowColorsWidth()
	{
		return 300;
	}

	String KEY_GLAMOUR_GIZMO = "glamourGizmo";
	@ConfigItem(
		keyName = KEY_GLAMOUR_GIZMO,
		name = "",
		description = "",
		hidden = true
	)
	default boolean glamourGizmo()
	{
		return false;
	}

	String KEY_COLOR_GROUP_HUE_DIST = "colorGroupHueDist";
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_HUE_DIST,
		name = "Color Group Hue Distance",
		description = "Max hue distance for color grouping (0 = identical only, 1 = any).",
		hidden = true
	)
	default double colorGroupHueDist()
	{
		return ColorGroupSettings.DEFAULT.getMaxHueDist();
	}
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_HUE_DIST,
		name = "",
		description = "",
		hidden = true
	)
	void setColorGroupHueDist(double dist);


	String KEY_COLOR_GROUP_SAT_DIST = "colorGroupSatDist";
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_SAT_DIST,
		name = "Color Group Saturation Distance",
		description = "Max saturation distance for color grouping (0 = identical only, 1 = any).",
		hidden = true
	)
	default double colorGroupSatDist()
	{
		return ColorGroupSettings.DEFAULT.getMaxSatDist();
	}
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_SAT_DIST,
		name = "",
		description = "",
		hidden = true
	)
	void setColorGroupSatDist(double dist);


	String KEY_COLOR_GROUP_LUM_DIST = "colorGroupLumDist";
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_LUM_DIST,
		name = "Color Group Luminance Distance",
		description = "Max luminance distance for color grouping (0 = identical only, 1 = any).",
		hidden = true
	)
	default double colorGroupLumDist()
	{
		return ColorGroupSettings.DEFAULT.getMaxLumDist();
	}
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_LUM_DIST,
		name = "",
		description = "",
		hidden = true
	)
	void setColorGroupLumDist(double dist);


	String KEY_COLOR_GROUP_SEPARATE_GRAYSCALE = "colorGroupSeparateGrayscale";
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_SEPARATE_GRAYSCALE,
		name = "Color Group Separate Grayscale",
		description = "",
		hidden = true
	)
	default boolean colorGroupSeparateGrayscale()
	{
		return ColorGroupSettings.DEFAULT.isSeparateGrayscale();
	}
	@ConfigItem(
		keyName = KEY_COLOR_GROUP_SEPARATE_GRAYSCALE,
		name = "Color Group Separate Grayscale",
		description = "",
		hidden = true
	)
	void setColorGroupSeparateGrayscale(boolean separateGrayscale);
}

package io.huze.glamourer;

import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
public class CsvLoader
{
	private static final String BASE_URL = "https://raw.githubusercontent.com/jhughes/glamourer_data/master/v1/";

	private final OkHttpClient httpClient;
	private final String baseUrl;
	private final File cacheDir;
	private final File devSheetDir;

	@Inject
	public CsvLoader(OkHttpClient httpClient, @Named("developerMode") boolean developerMode)
	{
		this(httpClient, BASE_URL, new File(RuneLite.RUNELITE_DIR, "glamourer"), devSheetDir(developerMode));
	}

	CsvLoader(OkHttpClient httpClient, String baseUrl, File cacheDir, @Nullable File devSheetDir)
	{
		this.httpClient = httpClient.newBuilder()
			.connectTimeout(Duration.ofSeconds(5))
			.readTimeout(Duration.ofSeconds(5))
			.build();
		this.baseUrl = baseUrl;
		this.cacheDir = cacheDir;
		this.devSheetDir = devSheetDir;
	}

	private static @Nullable File devSheetDir(boolean developerMode)
	{
		String dir = System.getProperty("glamourer.sheets");
		return developerMode && dir != null ? new File(dir) : null;
	}

	public static @Nonnull <T> List<T> parseList(String column, Function<String, T> elementMapper)
	{
		if (column.isEmpty())
		{
			return List.of();
		}
		List<T> parsed = new ArrayList<>();
		for (String part : column.split("\\|"))
		{
			parsed.add(elementMapper.apply(part.trim()));
		}
		return Collections.unmodifiableList(parsed);
	}

	public @Nonnull <T> List<T> load(String filename, String[] expectedHeaders, Function<String[], T> rowMapper)
	{
		if (devSheetDir != null)
		{
			try
			{
				return parse(new FileInputStream(new File(devSheetDir, filename)), expectedHeaders, rowMapper);
			}
			catch (IOException e)
			{
				throw new RuntimeException("Failed to load " + filename + " from " + devSheetDir, e);
			}
		}

		try
		{
			byte[] remote = fetchRemote(filename);
			List<T> rows = parse(new ByteArrayInputStream(remote), expectedHeaders, rowMapper);
			cache(filename, remote);
			return rows;
		}
		catch (Exception e)
		{
			log.warn("Failed to load remote {}. Trying the cached copy", filename, e);
		}
		try
		{
			return parse(new FileInputStream(new File(cacheDir, filename)), expectedHeaders, rowMapper);
		}
		catch (IOException e)
		{
			throw new RuntimeException("No remote or cached copy of " + filename, e);
		}
	}

	private @Nonnull <T> List<T> parse(InputStream is, String[] expectedHeaders, Function<String[], T> rowMapper) throws IOException
	{
		List<T> results = new ArrayList<>();
		try (BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8)))
		{
			String line;
			int[] columnMapping = null;
			String[] reordered = new String[expectedHeaders.length];
			while ((line = br.readLine()) != null)
			{
				if (line.isBlank() || line.startsWith("#"))
				{
					continue;
				}
				if (columnMapping == null)
				{
					columnMapping = buildColumnMapping(line, expectedHeaders);
					continue;
				}
				String[] unordered = line.split(",", -1);
				for (int i = 0; i < expectedHeaders.length; i++)
				{
					reordered[i] = unordered[columnMapping[i]].trim();
				}
				results.add(rowMapper.apply(reordered));
			}
		}
		return results;
	}

	private int[] buildColumnMapping(String headerLine, String[] expectedHeaders) throws IOException
	{
		String[] actualHeaders = headerLine.split(",", -1);
		Map<String, Integer> nameToIndex = new HashMap<>();
		for (int i = 0; i < actualHeaders.length; i++)
		{
			nameToIndex.put(actualHeaders[i].trim(), i);
		}
		int[] mapping = new int[expectedHeaders.length];
		for (int i = 0; i < expectedHeaders.length; i++)
		{
			Integer idx = nameToIndex.get(expectedHeaders[i]);
			if (idx == null)
			{
				throw new IOException(
					"Missing expected column '" + expectedHeaders[i] + "' in headers: " + Arrays.toString(actualHeaders));
			}
			mapping[i] = idx;
		}
		return mapping;
	}

	private byte[] fetchRemote(String filename) throws IOException
	{
		final var startTime = System.nanoTime();
		Request request = new Request.Builder()
			.url(baseUrl + filename)
			.build();
		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("HTTP " + response.code() + " fetching " + filename);
			}
			byte[] body = response.body().bytes();
			log.debug("Fetched {} from GitHub in {}ms", filename, (System.nanoTime() - startTime) / 1_000_000);
			return body;
		}
	}

	/// The last good fetch, kept for runs where the repo is unreachable. Written only after the
	/// content parsed, so a bad publish can't poison it.
	private void cache(String filename, byte[] content)
	{
		try
		{
			cacheDir.mkdirs();
			Path target = new File(cacheDir, filename).toPath();
			Path temp = new File(cacheDir, filename + ".tmp").toPath();
			Files.write(temp, content);
			Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Failed to cache {}", filename, e);
		}
	}
}

package io.huze.glamourer;

import io.huze.glamourer.item.DedupeItemManager;
import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.gameval.InventoryID;

public class Extensions
{
	public static <T extends Collection<Integer>> int[] toIntArray(T collection)
	{
		int[] array = new int[collection.size()];
		int i = 0;
		for (int x : collection)
		{
			array[i++] = x;
		}
		return array;
	}

	public static <T extends Collection<Short>> short[] toShortArray(T collection)
	{
		short[] array = new short[collection.size()];
		int i = 0;
		for (short s : collection)
		{
			array[i++] = s;
		}
		return array;
	}

	@Nullable
	public static short[] nullIfEmpty(@Nullable short[] array)
	{
		return array == null || array.length == 0 ? null : array;
	}

	private static final short[] EMPTY_SHORTS = {};

	@Nonnull
	public static short[] emptyIfNull(@Nullable short[] array)
	{
		return array == null ? EMPTY_SHORTS : array;
	}

	public static void arrayCopyEqualLength(@Nullable short[] src, @Nullable short[] dest)
	{
		int srcLength = src == null ? 0 : src.length;
		int destLength = dest == null ? 0 : dest.length;
		if (srcLength != destLength)
		{
			throw new IllegalArgumentException("arrayCopyEqualLength " + srcLength + " != " + destLength);
		}
		if (srcLength > 0)
		{
			System.arraycopy(src, 0, dest, 0, srcLength);
		}
	}

	public static String toHex(short[] array)
	{
		if (array == null)
		{
			return "";
		}

		StringBuilder sb = new StringBuilder(array.length * 4);
		for (short s : array)
		{
			sb.append(String.format("%04x", s & 0xFFFF));
		}
		return sb.toString();
	}

	public static String toHex(Collection<Short> collection)
	{
		if (collection == null)
		{
			return "";
		}

		StringBuilder sb = new StringBuilder(collection.size() * 4);
		for (short s : collection)
		{
			sb.append(String.format("%04x", s & 0xFFFF));
		}
		return sb.toString();
	}

	public static Set<Integer> getWornItemIds(Client client)
	{
		Set<Integer> wornIds = new HashSet<>();

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null && localPlayer.getPlayerComposition() != null)
		{
			int[] equipmentIds = localPlayer.getPlayerComposition().getEquipmentIds();
			for (int equipmentId : equipmentIds)
			{
				if (equipmentId >= PlayerComposition.ITEM_OFFSET)
				{
					int itemId = equipmentId - PlayerComposition.ITEM_OFFSET;
					wornIds.add(itemId);
				}
			}
		}

		// This is redundant with the previous block unless the user is using an item replacement plugin.
		// If the user is replacing items, this will include both the worn item and its replacement.
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment != null)
		{
			for (Item item : equipment.getItems())
			{
				if (item.getId() >= 0)
				{
					wornIds.add(item.getId());
				}
			}
		}
		return wornIds;
	}

	public static Set<Integer> getLocalPlayerItemIds(Client client)
	{
		var playerItemIds = getWornItemIds(client);
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() >= 0)
				{
					playerItemIds.add(item.getId());
				}
			}
		}
		return playerItemIds;
	}

	public static Set<Integer> getLocalPlayerEquippableItemIds(Client client, DedupeItemManager itemManager)
	{
		var playerItemIds = getWornItemIds(client);
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() >= 0 && itemManager.isEquippable(item.getId()))
				{
					playerItemIds.add(item.getId());
				}
			}
		}
		return playerItemIds;
	}
}

package io.huze.glamourer;

import com.google.inject.Provides;
import io.huze.glamourer.glam.GlamourEngine;
import io.huze.glamourer.glam.Glamourer;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.party.PartyInterface;
import io.huze.glamourer.party.PlayerBlacklist;
import io.huze.glamourer.item.DummyItemSheet;
import io.huze.glamourer.item.DedupeItemManager;
import io.huze.glamourer.item.ItemEquipSheet;
import io.huze.glamourer.item.ItemRenderSheet;
import io.huze.glamourer.item.ItemSheet;
import io.huze.glamourer.item.PetSheet;
import io.huze.glamourer.item.StackVariantSheet;
import io.huze.glamourer.plate.ChangeLog;
import io.huze.glamourer.plate.PlateManager;
import io.huze.glamourer.npc.PetGlamourSync;
import io.huze.glamourer.npc.NpcGlamourer;
import io.huze.glamourer.npc.NpcSheet;
import io.huze.glamourer.texture.SamplableTextureProvider;
import io.huze.glamourer.ui.ItemGlamourWindows;
import io.huze.glamourer.ui.MainPanel;
import io.huze.glamourer.ui.colorpicker.ColorDisplay;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@ExtensionMethod({Extensions.class})
@PluginDescriptor(
	name = "Glamourer"
)
public class Plugin extends net.runelite.client.plugins.Plugin
{
	@Inject
	Client client;
	@Inject
	ClientThread clientThread;
	@Inject
	Config config;
	@Inject
	ClientToolbar clientToolbar;
	@Inject
	ItemSheet itemSheet;
	@Inject
	ItemRenderSheet itemRenderSheet;
	@Inject
	ItemEquipSheet itemEquipSheet;
	@Inject
	PetSheet petSheet;
	@Inject
	StackVariantSheet stackVariantSheet;
	@Inject
	DummyItemSheet dummyItemSheet;
	@Inject
	NpcSheet npcSheet;
	@Inject
	DedupeItemManager ddItemManager;
	@Inject
	PlateManager plateManager;
	@Inject
	CsvLoader csvLoader;
	@Inject
	EventBus eventBus;
	@Inject
	GlamourEngine glamourEngine;
	@Inject
	Glamourer glamourer;
	@Inject
	PartyInterface partyInterface;
	@Inject
	PlayerBlacklist playerBlacklist;
	@Inject
	ChangeLog changeLog;
	@Inject
	IconService iconService;
	@Inject
	NpcGlamourer npcGlamourer;
	@Inject
	PetGlamourSync petGlamourSync;
	@Inject
	ItemGlamourWindows itemGlamourWindows;
	@Inject
	SamplableTextureProvider textureProvider;
	NavigationButton navButton;
	MainPanel panel;
	volatile boolean isStarted;

	@Override
	protected void startUp()
	{
		isStarted = true;
		final int startUpState = client.getGameState().getState();
		eventBus.register(glamourEngine);
		panel = injector.getInstance(MainPanel.class);
		setUpNavBar();
		applyShadeIntensity();
		clientThread.invokeLater(() -> {
			if (!isStarted)
			{
				return true;
			}
			if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
			{
				return false;
			}
			textureProvider.loadIfStale();
			try
			{
				if (!itemSheet.isLoadedOrRethrow()
					|| !itemRenderSheet.isLoadedOrRethrow()
					|| !itemEquipSheet.isLoadedOrRethrow()
					|| !petSheet.isLoadedOrRethrow()
					|| !stackVariantSheet.isLoadedOrRethrow()
					|| !dummyItemSheet.isLoadedOrRethrow()
					|| !npcSheet.isLoadedOrRethrow())
				{
					return false;
				}
				csvLoader = null;
				ddItemManager.initializeOnClientThread();
				plateManager.loadPlates().thenRun(() -> {
					if (!isStarted)
					{
						return;
					}
					plateManager.reapplyAllPlates();
					changeLog.setOnGlamourChanged(itemIds -> {
						if (itemIds.isEmpty())
						{
							partyInterface.sendUpdate();
						}
						else
						{
							partyInterface.sendPatch(itemIds);
						}
					});
					partyInterface.startUp();
					eventBus.register(partyInterface);
					if (startUpState >= GameState.LOADING.getState())
					{
						glamourEngine.backfillPlayerState();
					}
					tryCreateStarterPlate();
					promptOrphanRecovery();
				}).exceptionally(ex -> {
					log.error("Plugin startup failed", ex);
					return null;
				});
			}
			catch (Exception ex)
			{
				SwingUtilities.invokeLater(() -> panel.showError(ex));
			}
			return true;
		});

		npcGlamourer.startUp();
		petGlamourSync.startUp();
		glamourEngine.setOnGlamoursChanged(petGlamourSync::sync);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			tryCreateStarterPlate();
		}
	}

	private void tryCreateStarterPlate()
	{
		if (!plateManager.isStarterPlateNeeded() || client.getGameState() != GameState.LOGGED_IN)
		{
			// Try again later
			return;
		}
		clientThread.invokeLater(() -> {
			if (!plateManager.isStarterPlateNeeded())
			{
				return true;
			}
			if (client.getLocalPlayer() == null)
			{
				return false;
			}
			if (!plateManager.getPlates().isEmpty())
			{
				// User has created a plate, don't make a starter plate.
				return true;
			}
			var wornItemIds = client.getWornItemIds();
			if (wornItemIds.isEmpty())
			{
				return false;
			}
			plateManager.createStarterPlate(wornItemIds);
			return true;
		});
	}

	private void promptOrphanRecovery()
	{
		final int count = plateManager.getOrphanedPlateCount();
		if (count <= 0)
		{
			return;
		}
		var pluralPlates = count + " misplaced Glamour plate" + (count == 1 ? "" : "s");
		SwingUtilities.invokeLater(() -> {
			String[] options = {"Yes", "No", "Delete permanently"};
			int result = JOptionPane.showOptionDialog(
				null,
				"Glamourer has found " + pluralPlates + " in your configuration.\n" +
					"Would you like to recover " + pluralPlates + "?",
				"Glamourer",
				JOptionPane.DEFAULT_OPTION,
				JOptionPane.QUESTION_MESSAGE,
				null,
				options,
				options[0]
			);
			if (result == 0)
			{
				clientThread.invokeLater(() -> {
					plateManager.recoverOrphanedPlates();
				});
			}
			else if (result == 2)
			{
				clientThread.invokeLater(() -> {
					plateManager.discardOrphanedPlates();
				});
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(Config.GROUP))
		{
			var key = event.getKey();
			if (key.equals(Config.KEY_NAV_PRIORITY) || key.equals(Config.KEY_HIDE_SIDEBAR_ICON))
			{
				setUpNavBar();
			}
			if (key.equals(Config.KEY_ICON_SCALE))
			{
				iconService.clearCache();
			}
			if (key.equals(Config.KEY_SHADE_INTENSITY))
			{
				applyShadeIntensity();
			}
		}
	}

	private void applyShadeIntensity()
	{
		SwingUtilities.invokeLater(() -> ColorDisplay.setLightIntensity(config.shadeIntensity() / 100.0));
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		changeLog.clear();
		playerBlacklist.load();
		try
		{
			plateManager.loadPlates().thenRun(() ->
			{
				plateManager.reapplyAllPlates();
				tryCreateStarterPlate();
				promptOrphanRecovery();
			});
		}
		catch (Exception ex)
		{
			SwingUtilities.invokeLater(() -> panel.showError(ex));
		}
	}

	private void setUpNavBar()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (config.hideSidebarIcon())
		{
			return;
		}
		navButton = NavigationButton.builder()
			.tooltip("Glamourer")
			.icon(ImageUtil.loadImageResource(getClass(), "nav_icon.png"))
			.priority(config.navPriority())
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		isStarted = false;
		SwingUtilities.invokeLater(itemGlamourWindows::closeAll);
		changeLog.setOnGlamourChanged(itemIds -> {});
		changeLog.setOnUndoRedoAvailabilityChanged(() -> {});
		plateManager.setOnPlatesChanged(ignored -> {});
		partyInterface.setOnStateChanged(() -> {});
		changeLog.clear();
		glamourEngine.setOnGlamoursChanged(() -> {});
		petGlamourSync.shutDown();
		npcGlamourer.shutDown();
		eventBus.unregister(glamourEngine);
		eventBus.unregister(partyInterface);
		partyInterface.shutDown();
		glamourEngine.revertAll();
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
	}

	@Provides
	Config provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(Config.class);
	}
}

package io.huze.glamourer;

import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public abstract class Sheet<T>
{
	private final String filename;
	private final String[] headers;
	private final Function<String[], T> rowMapper;

	@Inject
	private CsvLoader csvLoader;
	private CompletableFuture<Void> future;

	protected Sheet(String filename, String[] headers, Function<String[], T> rowMapper)
	{
		this.filename = filename;
		this.headers = headers;
		this.rowMapper = rowMapper;
	}

	/// Guice injects fields before methods, so the loader is set by the time this runs.
	@Inject
	public final void start()
	{
		future = CompletableFuture.runAsync(() -> {
			final var startTime = System.nanoTime();
			load(csvLoader.load(filename, headers, rowMapper));
			log.debug("{} loaded in {}ms", getClass().getSimpleName(), (System.nanoTime() - startTime) / 1_000_000);
		});
	}

	public final boolean isLoadedOrRethrow()
	{
		if (future.isCompletedExceptionally())
		{
			future.join();
		}
		return future.isDone();
	}

	protected abstract void load(List<T> rows);
}

package io.huze.glamourer.color;

import java.awt.Color;
import javax.annotation.Nonnull;

/// Jagex HSL to RGB, adjusted by the client's brightness setting.
public final class Brightness
{
	/// The client's brightness values run from 0.9 (dimmest) to 0.6 (brightest).
	public static final double DEFAULT = 0.8;

	private static final int CHANNEL_RANGE = 256;

	/// Rebuilt on the client thread when the brightness changes. The UI reads the last one built.
	private static volatile Brightness current = new Brightness(DEFAULT);

	private final double brightness;
	private final int[] gammaTable;

	@Nonnull
	public static Brightness getCurrent()
	{
		return current;
	}

	/// Client thread only.
	@Nonnull
	public static Brightness of(double brightness)
	{
		var loaded = current;
		if (!loaded.isForBrightness(brightness))
		{
			loaded = new Brightness(brightness);
			current = loaded;
		}
		return loaded;
	}

	Brightness(double brightness)
	{
		this.brightness = brightness;
		this.gammaTable = new int[CHANNEL_RANGE];
		for (int channel = 0; channel < CHANNEL_RANGE; channel++)
		{
			gammaTable[channel] = (int) (Math.pow((double) channel / CHANNEL_RANGE, brightness) * CHANNEL_RANGE);
		}
	}

	boolean isForBrightness(double brightness)
	{
		return this.brightness == brightness;
	}

	public int toRgb(short hsl)
	{
		var color = Colors.hslToColor(hsl);
		return (gammaTable[color.getRed()] << 16)
			| (gammaTable[color.getGreen()] << 8)
			| gammaTable[color.getBlue()];
	}

	@Nonnull
	public Color applyBrightness(@Nonnull Color color)
	{
		return new Color(
			gammaTable[color.getRed()], gammaTable[color.getGreen()], gammaTable[color.getBlue()]);
	}
}

package io.huze.glamourer.color;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import net.runelite.api.JagexColor;

public class ColorGroup
{
	private static final short SKIN_COLOR = 4550;
	private static final short HAIR_COLOR = 6798;
	private static final short EYE_COLOR = 0;
	// Anchor is the first color added (used for offset calculations)
	private final int anchorHue;
	private final int anchorSat;
	private final int anchorLum;
	private final ColorGroupSettings settings;

	// Indices into the glamour's color array
	@Getter
	private final List<Integer> colorIndices = new ArrayList<>();

	// Each color's [hDelta, sDelta, lDelta] offset from anchor (based on original colors)
	@Getter
	private final List<int[]> offsets = new ArrayList<>();

	// All original HSL values in this group (for checking if new colors can join)
	private final List<short[]> originalHslValues = new ArrayList<>();

	private ColorGroup(short anchorHsl, ColorGroupSettings settings)
	{
		this.anchorHue = JagexColor.unpackHue(anchorHsl);
		this.anchorSat = JagexColor.unpackSaturation(anchorHsl);
		this.anchorLum = JagexColor.unpackLuminance(anchorHsl);
		this.settings = settings;
	}

	private void addColor(int index, short originalHsl)
	{
		int h = JagexColor.unpackHue(originalHsl);
		int s = JagexColor.unpackSaturation(originalHsl);
		int l = JagexColor.unpackLuminance(originalHsl);

		colorIndices.add(index);
		offsets.add(new int[]{h - anchorHue, s - anchorSat, l - anchorLum});
		originalHslValues.add(new short[]{(short) h, (short) s, (short) l});
	}

	// When grays are separated, saturated colors get a more generous luminance threshold
	// since grays are already excluded and color ramps (same hue, varying luminance) should group together
	private static final double SATURATED_LUM_BOOST = 3.0;

	private boolean areGroupable(int h1, int s1, int l1, int h2, int s2, int l2)
	{
		if (settings.isSeparateGrayscale() && (s1 == 0) != (s2 == 0))
		{
			return false;
		}
		double hDiff = Math.abs(h1 - h2) / 64.0;
		hDiff = Math.min(hDiff, 1.0 - hDiff); // circular
		double sDiff = Math.abs(s1 - s2) / 8.0;
		double lDiff = Math.abs(l1 - l2) / 128.0;
		double maxLum = settings.getMaxLumDist();
		if (settings.isSeparateGrayscale() && s1 > 0 && s2 > 0)
		{
			maxLum = Math.min(maxLum * SATURATED_LUM_BOOST, 1.0);
		}
		return hDiff <= settings.getMaxHueDist()
			&& sDiff <= settings.getMaxSatDist()
			&& lDiff <= maxLum;
	}

	private boolean canGroup(short hsl)
	{
		if (hsl == SKIN_COLOR || containsSkinColor())
		{
			return false;
		}

		int h = JagexColor.unpackHue(hsl);
		int s = JagexColor.unpackSaturation(hsl);
		int l = JagexColor.unpackLuminance(hsl);

		for (short[] existing : originalHslValues)
		{
			if (areGroupable(h, s, l, existing[0], existing[1], existing[2]))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isGray()
	{
		return !originalHslValues.isEmpty() && originalHslValues.get(0)[1] == 0;
	}

	private boolean containsSkinColor()
	{
		for (short[] hsl : originalHslValues)
		{
			if (JagexColor.packHSL(hsl[0], hsl[1], hsl[2]) == SKIN_COLOR)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Checks if the replacement colors still maintain the expected relative offsets.
	 * If any color has been individually edited to break the pattern, returns false.
	 *
	 * @param pairs The color pairs to check
	 * @return true if replacements are coherent (maintain same relative offsets), false otherwise
	 */
	public boolean areReplacementsCoherent(List<ColorReplacement> pairs)
	{
		if (colorIndices.size() <= 1)
		{
			return true;
		}

		// Get the first replacement color as reference
		ColorReplacement firstPair = pairs.get(colorIndices.get(0));
		int refH = JagexColor.unpackHue(firstPair.getReplacement());
		int refS = JagexColor.unpackSaturation(firstPair.getReplacement());
		int refL = JagexColor.unpackLuminance(firstPair.getReplacement());

		// Check if all other colors maintain the same relative offsets
		for (int i = 1; i < colorIndices.size(); i++)
		{
			int colorIdx = colorIndices.get(i);
			int[] expectedOffset = offsets.get(i);

			ColorReplacement pair = pairs.get(colorIdx);
			int actualH = JagexColor.unpackHue(pair.getReplacement());
			int actualS = JagexColor.unpackSaturation(pair.getReplacement());
			int actualL = JagexColor.unpackLuminance(pair.getReplacement());

			// Calculate expected values based on first replacement + original offset
			// Hue wraps around (circular), sat/lum clamp
			int expectedH = ((refH + expectedOffset[0]) % 64 + 64) % 64;
			int expectedS = clamp(refS + expectedOffset[1], 0, 7);
			int expectedL = clamp(refL + expectedOffset[2], 0, 127);

			// Allow small tolerance for clamping/rounding effects
			// For hue, also check wrapped distance (e.g., 0 and 63 are close)
			int hueDiff = Math.abs(actualH - expectedH);
			int wrappedHueDiff = 64 - hueDiff;
			if (Math.min(hueDiff, wrappedHueDiff) > 1 ||
				Math.abs(actualS - expectedS) > 0 ||
				Math.abs(actualL - expectedL) > 1)
			{
				return false;
			}
		}

		return true;
	}

	public static List<ColorGroup> groupColors(List<ColorReplacement> pairs, ColorGroupSettings settings)
	{
		List<ColorGroup> groups = assignToInitialGroups(pairs, settings);
		mergeConnectedGroups(groups);
		finalizeGroups(groups);
		return groups;
	}

	private static List<ColorGroup> assignToInitialGroups(List<ColorReplacement> pairs, ColorGroupSettings settings)
	{
		List<ColorGroup> groups = new ArrayList<>();
		int index = 0;

		for (ColorReplacement pair : pairs)
		{
			short originalHsl = pair.getOriginal();
			ColorGroup matchingGroup = findMatchingGroup(groups, originalHsl);

			if (matchingGroup != null)
			{
				matchingGroup.addColor(index, originalHsl);
			}
			else
			{
				ColorGroup newGroup = new ColorGroup(originalHsl, settings);
				newGroup.addColor(index, originalHsl);
				groups.add(newGroup);
			}
			index++;
		}
		return groups;
	}

	private static ColorGroup findMatchingGroup(List<ColorGroup> groups, short hsl)
	{
		for (ColorGroup group : groups)
		{
			if (group.canGroup(hsl))
			{
				return group;
			}
		}
		return null;
	}

	private static void mergeConnectedGroups(List<ColorGroup> groups)
	{
		boolean merged;
		do
		{
			merged = tryMergeOnePair(groups);
		} while (merged);
	}

	private static boolean tryMergeOnePair(List<ColorGroup> groups)
	{
		for (int i = 0; i < groups.size(); i++)
		{
			for (int j = i + 1; j < groups.size(); j++)
			{
				if (groups.get(i).shouldMergeWith(groups.get(j)))
				{
					groups.get(i).mergeFrom(groups.get(j));
					groups.remove(j);
					return true;
				}
			}
		}
		return false;
	}

	private static void finalizeGroups(List<ColorGroup> groups)
	{
		for (ColorGroup group : groups)
		{
			group.sortByLuminance();
		}
		groups.sort((a, b) -> {
			int aOrder = a.containsSkinColor() ? 2 : a.isGray() ? 1 : 0;
			int bOrder = b.containsSkinColor() ? 2 : b.isGray() ? 1 : 0;
			if (aOrder != bOrder)
			{
				return Integer.compare(aOrder, bOrder);
			}
			if (aOrder == 1)
			{
				// Grays: sort by luminance descending (brighter first)
				return Short.compare(b.originalHslValues.get(0)[2], a.originalHslValues.get(0)[2]);
			}
			return Short.compare(a.originalHslValues.get(0)[0], b.originalHslValues.get(0)[0]);
		});
	}

	/**
	 * Checks if this group should be merged with another group.
	 * Returns true if any color in this group is within threshold of any color in the other group.
	 */
	private boolean shouldMergeWith(ColorGroup other)
	{
		if (containsSkinColor() || other.containsSkinColor())
		{
			return false;
		}
		for (short[] myHsl : originalHslValues)
		{
			for (short[] otherHsl : other.originalHslValues)
			{
				if (areGroupable(myHsl[0], myHsl[1], myHsl[2],
					otherHsl[0], otherHsl[1], otherHsl[2]))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Merges all colors from another group into this group.
	 */
	private void mergeFrom(ColorGroup other)
	{
		colorIndices.addAll(other.colorIndices);
		offsets.addAll(other.offsets);
		originalHslValues.addAll(other.originalHslValues);
	}

	/**
	 * Sorts the colors in this group by luminance (brightest first).
	 * Recalculates offsets relative to the new first color.
	 */
	private void sortByLuminance()
	{
		if (colorIndices.size() <= 1)
		{
			return;
		}

		Integer[] sortOrder = createLuminanceSortOrder();
		reorderBySortOrder(sortOrder);
		recalculateOffsets();
	}

	private Integer[] createLuminanceSortOrder()
	{
		Integer[] sortOrder = new Integer[colorIndices.size()];
		for (int i = 0; i < sortOrder.length; i++)
		{
			sortOrder[i] = i;
		}

		java.util.Arrays.sort(sortOrder, (a, b) -> {
			short[] hslA = originalHslValues.get(a);
			short[] hslB = originalHslValues.get(b);
			int cmp = Short.compare(hslB[2], hslA[2]); // Luminance descending
			if (cmp != 0) return cmp;
			cmp = Short.compare(hslA[0], hslB[0]); // Hue ascending
			if (cmp != 0) return cmp;
			return Short.compare(hslA[1], hslB[1]); // Saturation ascending
		});

		return sortOrder;
	}

	private void reorderBySortOrder(Integer[] sortOrder)
	{
		List<Integer> newColorIndices = new ArrayList<>();
		List<int[]> newOffsets = new ArrayList<>();
		List<short[]> newOriginalHslValues = new ArrayList<>();

		for (int i : sortOrder)
		{
			newColorIndices.add(colorIndices.get(i));
			newOffsets.add(offsets.get(i));
			newOriginalHslValues.add(originalHslValues.get(i));
		}

		colorIndices.clear();
		colorIndices.addAll(newColorIndices);
		offsets.clear();
		offsets.addAll(newOffsets);
		originalHslValues.clear();
		originalHslValues.addAll(newOriginalHslValues);
	}

	private void recalculateOffsets()
	{
		short[] newAnchor = originalHslValues.get(0);
		for (int i = 0; i < offsets.size(); i++)
		{
			short[] hsl = originalHslValues.get(i);
			offsets.set(i, new int[]{hsl[0] - newAnchor[0], hsl[1] - newAnchor[1], hsl[2] - newAnchor[2]});
		}
	}

	/**
	 * Calculates the new HSL value for a color in this group when the anchor color changes.
	 *
	 * @param newAnchorHsl The new HSL value for the anchor (from user selection)
	 * @param offsetIndex  Index into the offsets list for the specific color
	 * @return Adjusted HSL value for the color (hue wraps, sat/lum clamp)
	 */
	public short calculateNewColor(short newAnchorHsl, int offsetIndex)
	{
		int newH = JagexColor.unpackHue(newAnchorHsl);
		int newS = JagexColor.unpackSaturation(newAnchorHsl);
		int newL = JagexColor.unpackLuminance(newAnchorHsl);

		int[] offset = offsets.get(offsetIndex);
		int finalH = ((newH + offset[0]) % 64 + 64) % 64;
		int finalS = clamp(newS + offset[1], 0, 7);
		int finalL = clamp(newL + offset[2], 0, 127);

		return JagexColor.packHSL(finalH, finalS, finalL);
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package io.huze.glamourer.color;

import lombok.Value;

@Value
public class ColorGroupSettings
{
	double maxHueDist; // 0.0-1.0 (0 = identical hue only, 1 = any hue)
	double maxSatDist; // 0.0-1.0
	double maxLumDist; // 0.0-1.0
	boolean separateGrayscale;

	public static final ColorGroupSettings DEFAULT = new ColorGroupSettings(0.04, 0.4, 0.08, true);
}

package io.huze.glamourer.color;

import java.io.Serializable;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.Setter;

public class ColorReplacement implements Serializable
{
	@Getter
	private final short original;
	@Getter
	@Setter
	private short replacement;
	/// Only stored when it differs from the original.
	/// TODO swap to storing model as the primary original color.
	@Nullable
	private final Short model;

	public ColorReplacement(short model, short original, short replacement)
	{
		this.original = original;
		this.replacement = replacement;
		this.model = model == original ? null : model;
	}

	public ColorReplacement(short original, short replacement)
	{
		this(original, original, replacement);
	}

	public short getModel()
	{
		return model == null ? original : model;
	}

	public boolean hasChanged()
	{
		return original != replacement;
	}

	@Override
	public String toString()
	{
		return String.format("<%d,%d>", original, replacement);
	}
}

package io.huze.glamourer.color;

import java.awt.Color;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import net.runelite.api.JagexColor;
import static net.runelite.api.JagexColor.packHSL;
import static net.runelite.api.JagexColor.unpackHue;
import static net.runelite.api.JagexColor.unpackLuminance;
import static net.runelite.api.JagexColor.unpackSaturation;

public class Colors
{
	// Inclusive max ints
	public static final int MAX_HUE = JagexColor.HUE_MAX;
	public static final int MAX_SAT = JagexColor.SATURATION_MAX;
	public static final int MAX_LUM = JagexColor.LUMINANCE_MAX;
	// Exclusive max doubles
	private static final double MAX_HUE_D = MAX_HUE + 1;
	private static final double MAX_SAT_D = MAX_SAT + 1;
	private static final double MAX_LUM_D = MAX_LUM + 1;

	private static final double HUE_OFFSET = (.5D / MAX_HUE_D);
	private static final double SATURATION_OFFSET = (.5D / MAX_SAT_D);
	private static final double HUE_CONE_COUNT = 6;

	public static String formatHSL(short hsl)
	{
		return String.format("%dH/%dS/%dL", unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl));
	}

	public static Color hslToColor(short hsl)
	{
		return hslToColor(unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl));
	}

	public static Color hslToColor(int hue, int sat, int lum)
	{
		double h = (hue / MAX_HUE_D + HUE_OFFSET) * HUE_CONE_COUNT;
		double s = (double) sat / MAX_SAT_D + SATURATION_OFFSET;
		double l = (double) lum / MAX_LUM_D;

		double chroma = (1D - Math.abs(2D * l - 1D)) * s;
		double x = chroma * (1D - Math.abs(h % 2D - 1D));
		double lightness = l - (chroma / 2D);

		double r = lightness, g = lightness, b = lightness;
		switch ((int) h)
		{
			case 0:
				r += chroma;
				g += x;
				break;
			case 1:
				g += chroma;
				r += x;
				break;
			case 2:
				g += chroma;
				b += x;
				break;
			case 3:
				b += chroma;
				g += x;
				break;
			case 4:
				b += chroma;
				r += x;
				break;
			default:
				r += chroma;
				b += x;
				break;
		}
		return new Color((int) (r * 256D), (int) (g * 256D), (int) (b * 256D));
	}

	public static Color hslToShadedColor(short hsl, int shade)
	{
		return hslToShadedColor(unpackHue(hsl), unpackSaturation(hsl), unpackLuminance(hsl), shade);
	}

	public static Color hslToShadedColor(int hue, int sat, int lum, int shade)
	{
		return hslToColor(hue, sat, Shade.scale(lum, shade));
	}

	/// Applied in order so replacements will chain.
	public static short applyReplacements(short value, @Nullable short[] find, @Nullable short[] replace)
	{
		if (find == null || replace == null)
		{
			return value;
		}
		for (int i = 0; i < find.length && i < replace.length; i++)
		{
			if (value == find[i])
			{
				value = replace[i];
			}
		}
		return value;
	}

	/**
	 * Nudge replace values to prevent sequential replacement from chaining.
	 * If replace[i] == find[j] for j > i, the engine applies both replacements to the same face.
	 * Identity replacements (find[j] == replace[j]) are skipped since they cause no visual change.
	 * <p>
	 * When a chain is detected, the nearest non-chaining color is found by searching outward
	 * from the original value: luminance ±1, ±2, ..., then saturation ±1, ±2, ..., then hue.
	 */
	public static void breakColorChains(@Nonnull short[] find, @Nonnull short[] replace)
	{
		assert find.length == replace.length;
		for (int i = 0; i < find.length; i++)
		{
			if (chainsForward(find, replace, i, replace[i]))
			{
				replace[i] = findNearestNonChaining(find, replace, i);
			}
		}
	}

	private static final int[] NUDGE_DIRECTIONS = {1, -1};
	private static final int HUE_SCALE = (MAX_LUM + 1) / (MAX_HUE + 1);
	private static final int SAT_SCALE = (MAX_LUM + 1) / (MAX_SAT + 1);

	private static short findNearestNonChaining(short[] find, short[] replace, int i)
	{
		final var original = replace[i];
		final var h = unpackHue(original);
		final var s = unpackSaturation(original);
		final var l = unpackLuminance(original);

		for (int d = 1; d <= MAX_LUM; d++)
		{
			for (int dir : NUDGE_DIRECTIONS)
			{
				int newL = l + d * dir;
				if (newL >= 0 && newL <= MAX_LUM)
				{
					short candidate = packHSL(h, s, newL);
					if (!chainsForward(find, replace, i, candidate))
					{
						return candidate;
					}
				}
			}

			if (d % HUE_SCALE == 0)
			{
				int hueOffset = d / HUE_SCALE;
				for (int dir : NUDGE_DIRECTIONS)
				{
					int newH = Math.floorMod(h + hueOffset * dir, MAX_HUE + 1);
					short candidate = packHSL(newH, s, l);
					if (!chainsForward(find, replace, i, candidate))
					{
						return candidate;
					}
				}
			}

			if (d % SAT_SCALE == 0)
			{
				int satOffset = d / SAT_SCALE;
				for (int dir : NUDGE_DIRECTIONS)
				{
					int newS = s + satOffset * dir;
					if (newS >= 0 && newS <= MAX_SAT)
					{
						short candidate = packHSL(h, newS, l);
						if (!chainsForward(find, replace, i, candidate))
						{
							return candidate;
						}
					}
				}
			}
		}

		return original;
	}

	private static boolean chainsForward(short[] find, short[] replace, int i, short value)
	{
		for (int j = i + 1; j < find.length; j++)
		{
			if (find[j] != replace[j] && value == find[j])
			{
				return true;
			}
		}
		return false;
	}
}

package io.huze.glamourer.color;

public final class Shade
{
	public static final int FULL = 128;
	public static final int AMBIENT = 64;
	/// The client clamps every face to this range.
	public static final int DARKEST = 2;
	public static final int BRIGHTEST = 126;
	private static final int LUMINANCE_MASK = 127;

	private Shade()
	{
	}

	public static int fade(int litShade, double intensity)
	{
		return (int) Math.round(FULL - (FULL - litShade) * intensity);
	}

	public static int scale(int value, int shade)
	{
		return value * shade / FULL;
	}

	public static short shadeHsl(short hsl, int shade)
	{
		int luminance = Math.max(DARKEST, Math.min(BRIGHTEST, scale(hsl & LUMINANCE_MASK, shade)));
		return (short) ((hsl & ~LUMINANCE_MASK) | luminance);
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.item.DedupeItemManager;
import javax.annotation.Nonnull;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class DataRepairer
{
	public static GlamourData tryRepairOrThrow(GlamourEngine engine, DedupeItemManager itemManager, @Nonnull GlamourData data)
	{
		assert data.getItemKey() != null;

		// Fix items whose names have been re-cased by game update.
		var recasedKey = itemManager.findKeyIgnoreCase(data.getItemKey());
		if (recasedKey != null)
		{
			log.info("Repaired corrupt key '{}' as re-cased '{}'", data.getItemKey(), recasedKey);
			return data.withNewKey(recasedKey);
		}

		// Fix items whose keys were corrupted by old glamourer's race condition.
		var itemIds = itemManager.getMatchingItemIdsForCorruptKey(data.getItemKey());
		log.info("Repairing corrupt key '{}' with {} potential items. Scores:", data.getItemKey(), itemIds.size());
		var bestScore = -1;
		PrimedItem bestItem = null;
		for (var itemId : itemIds)
		{
			var primedItem = engine.getPrimedItem(itemId);
			var score = computeColorMatchScore(data, primedItem);
			log.info("\t{} : {}", primedItem.getItemComposition().getMembersName(), score);
			if (score > bestScore)
			{
				bestItem = primedItem;
				bestScore = score;
			}
		}

		///  TODO In the future, we could give the user an option to choose what item to use.
		if (bestScore > 0)
		{
			log.info("Repaired corrupt key '{}' with '{}'", data.getItemKey(), bestItem.getDedupeKey());
			return data.withNewKey(bestItem.getDedupeKey());
		}
		throw new IllegalArgumentException("Unable to repair " + data.getItemKey());
	}

	static int computeColorMatchScore(GlamourData data, PrimedItem item)
	{
		int matchScore = 0;
		for (var replacement : data.getColorReplacements())
		{
			for (var primedReplacement : item.getColorReplacements())
			{
				if (replacement.getModel() == primedReplacement.getModel())
				{
					matchScore++;
				}
				if (replacement.getOriginal() == primedReplacement.getReplacement())
				{
					matchScore++;
				}
			}
		}
		return matchScore;
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.Extensions;
import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.color.Colors;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nonnull;
import lombok.Getter;
import lombok.experimental.ExtensionMethod;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.ItemComposition;

@Slf4j
@ExtensionMethod({Extensions.class})
class GlamState
{
	@Getter
	private final int model;
	@Nonnull
	private final short[] colorFind;
	@Nonnull
	private final short[] colorReplace;
	@Nonnull
	private final short[] textureFind;
	@Nonnull
	private final short[] textureReplace;
	private final boolean immutable;
	public final int colorLength;

	GlamState(final int model,
			  @Nonnull final short[] colorFind,
			  @Nonnull final short[] colorReplace,
			  @Nonnull final short[] textureFind,
			  @Nonnull final short[] textureReplace,
			  final boolean immutable)
	{
		this.model = model;
		assert colorFind.length == colorReplace.length;
		this.colorFind = colorFind;
		this.colorReplace = colorReplace;
		assert textureFind.length == textureReplace.length;
		this.textureFind = textureFind;
		this.textureReplace = textureReplace;
		this.immutable = immutable;
		this.colorLength = colorFind.length;
	}

	synchronized GlamState deepCopy(boolean immutable)
	{
		return new GlamState(
			model,
			colorFind.clone(),
			colorReplace.clone(),
			textureFind.clone(),
			textureReplace.clone(),
			immutable);
	}

	/// Assumes the state is primed
	synchronized void applyColorReplacements(List<ColorReplacement> replacements)
	{
		// Snapshot the original colorReplace so that mutations from earlier replacements
		// don't cause later replacements to match the wrong index.
		var originalColorReplace = colorReplace.clone();
		var applied = new boolean[replacements.size()];
		for (int i = 0; i < replacements.size(); i++)
		{
			applied[i] = applyModelColorReplacement(replacements.get(i));
		}
		for (int i = 0; i < replacements.size(); i++)
		{
			if (!applied[i])
			{
				applied[i] = applyOriginalColorReplacement(replacements.get(i), originalColorReplace);
			}
		}
		for (int i = 0; i < applied.length; i++)
		{
			if (!applied[i])
			{
				log.warn("Failed to apply color replacement: {}", replacements.get(i));
			}
		}
	}

	private boolean applyModelColorReplacement(ColorReplacement replacement)
	{
		for (int i = 0; i < colorFind.length; i++)
		{
			if (colorFind[i] == replacement.getModel())
			{
				replaceColor(i, replacement.getReplacement());
				return true;
			}
		}
		return false;
	}

	private boolean applyOriginalColorReplacement(ColorReplacement replacement, short[] originalColorReplace)
	{
		for (int i = 0; i < colorFind.length; i++)
		{
			if (originalColorReplace[i] == replacement.getOriginal())
			{
				replaceColor(i, replacement.getReplacement());
				return true;
			}
		}
		return false;
	}

	synchronized short getColor(int i)
	{
		return colorReplace[i];
	}

	synchronized void replaceColor(int i, short color)
	{
		if (immutable)
		{
			throw new IllegalStateException("Cannot modify immutable GlamState");
		}
		colorReplace[i] = color;
	}

	/// Assumes the state is primed
	synchronized void applyTextureReplacements(List<TextureReplacement> replacements)
	{
		for (TextureReplacement replacement : replacements)
		{
			apply(replacement);
		}
	}

	private void apply(TextureReplacement replacement)
	{
		for (int i = 0; i < textureFind.length; i++)
		{
			if (textureFind[i] == replacement.getOriginal())
			{
				replaceTexture(i, replacement.getReplacement());
			}
		}
	}

	synchronized void replaceTexture(int i, short textureId)
	{
		if (immutable)
		{
			throw new IllegalStateException("Cannot modify immutable GlamState");
		}
		textureReplace[i] = textureId;
	}

	synchronized void applyOriginalTo(final ItemComposition comp)
	{
		comp.setColorToReplace(colorFind);
		comp.setColorToReplaceWith(colorFind);
		comp.setTextureToReplace(textureFind.nullIfEmpty());
		comp.setTextureToReplaceWith(textureFind.nullIfEmpty());
	}

	synchronized void applyTo(final ItemComposition comp)
	{
		var colorReplace = this.colorReplace.clone();
		Colors.breakColorChains(colorFind, colorReplace);
		comp.setColorToReplace(colorFind);
		comp.setColorToReplaceWith(colorReplace);
		comp.setTextureToReplace(textureFind.nullIfEmpty());
		comp.setTextureToReplaceWith(textureReplace.nullIfEmpty());
	}

	@Nonnull
	synchronized ModelEdits getModelEdits()
	{
		var colorReplace = this.colorReplace.clone();
		Colors.breakColorChains(colorFind, colorReplace);
		return new ModelEdits(
			colorFind.clone(), colorReplace, textureFind.clone(), textureReplace.clone());
	}

	synchronized void applyTo(final ColorTextureOverride override)
	{
		var colorReplace = override.getColorToReplaceWith();
		Extensions.arrayCopyEqualLength(this.colorReplace, colorReplace);
		Colors.breakColorChains(colorFind, colorReplace);
		Extensions.arrayCopyEqualLength(textureReplace, override.getTextureToReplaceWith());
	}

	@Nonnull
	public synchronized List<ColorReplacement> getColorReplacements()
	{
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		for (int i = 0; i < colorFind.length; i++)
		{
			colorReplacements.add(new ColorReplacement(colorFind[i], colorReplace[i]));
		}
		return colorReplacements;
	}

	@Nonnull
	public synchronized List<TextureReplacement> getTextureReplacements()
	{
		List<TextureReplacement> textureReplacements = new ArrayList<>();
		for (int i = 0; i < textureFind.length; i++)
		{
			textureReplacements.add(new TextureReplacement(textureFind[i], textureReplace[i]));
		}
		return textureReplacements;
	}
}

package io.huze.glamourer.glam;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.ItemComposition;

@Slf4j
public class Glamour
{
	@Nullable
	private final String key;
	private final PrimedItem primedItem;
	@Getter
	private final Collection<Integer> itemIds;
	final GlamState staged;
	private final AtomicBoolean dirty = new AtomicBoolean();

	@Nonnull
	public GlamourData getData(boolean verbose)
	{
		return getData(-1, verbose);
	}

	@Nonnull
	public GlamourData getData(int itemId, boolean verbose)
	{
		var colorList = getColorReplacements().stream()
			.filter((cr) -> verbose || cr.hasChanged())
			.collect(Collectors.toList());

		var textureList = getTextureReplacements().stream()
			.filter(tr -> verbose || tr.hasChanged())
			.collect(Collectors.toList());

		return new GlamourData(
			itemId == -1 ? key : null,
			itemId == -1 ? getPrimaryItemId() : itemId,
			colorList,
			textureList.isEmpty() ? null : textureList);
	}

	/// Load glamour from serialized GlamourData.
	@Nonnull
	public static Glamour load(@Nonnull PrimedItem primedItem, @Nonnull Collection<Integer> duplicateItemIds, @Nonnull GlamourData data)
	{
		var glamState = primedItem.getPrimedState();
		var colorReplacements = data.getColorReplacements();
		glamState.applyColorReplacements(colorReplacements);
		var textureReplacements = data.getTextureReplacements();
		if (textureReplacements != null)
		{
			glamState.applyTextureReplacements(textureReplacements);
		}
		return new Glamour(data.getItemKey(), primedItem, duplicateItemIds, glamState);
	}

	@Nonnull
	public static Glamour start(@Nonnull PrimedItem primedItem, @Nonnull Collection<Integer> duplicateItemIds)
	{
		return new Glamour(primedItem.getDedupeKey(), primedItem, duplicateItemIds, primedItem.getPrimedState());
	}

	private Glamour(@Nullable String key,
					PrimedItem primedItem,
					Collection<Integer> itemIds,
					GlamState staged)
	{
		this.key = key;
		this.primedItem = primedItem;
		this.itemIds = itemIds;
		this.staged = staged;
	}

	protected Glamour(Glamour source)
	{
		this.key = source.key;
		this.primedItem = source.primedItem;
		this.itemIds = source.itemIds;
		this.staged = source.staged;
	}

	public int getPrimaryItemId()
	{
		return primedItem.getItemComposition().getId();
	}

	public String getItemName()
	{
		return primedItem.getName();
	}

	public boolean isEquivalent(Glamour other)
	{
		return this == other || other instanceof WornOnlyGlamour && this == ((WornOnlyGlamour) other).source;
	}

	protected void apply(ItemComposition itemComposition)
	{
		staged.applyTo(itemComposition);
	}

	private boolean sizeMismatch(@Nonnull ColorTextureOverride override)
	{
		{
			var expectedSize = staged.getColorReplacements().size();
			var actualSize = override.getColorToReplaceWith().length;
			if (expectedSize != actualSize)
			{
				log.warn("Mismatched color replace size ({} != {}) for item {}:{}", expectedSize, actualSize, getPrimaryItemId(), getItemName());
				return true;
			}
		}
		{
			var expectedSize = staged.getTextureReplacements().size();
			var textureReplace = override.getTextureToReplaceWith();
			var actualSize = textureReplace == null ? 0 : textureReplace.length;
			if (expectedSize != actualSize)
			{
				log.warn("Mismatched texture replace size ({} != {}) for item {}:{}", expectedSize, actualSize, getPrimaryItemId(), getItemName());
				return true;
			}
		}
		return false;
	}

	protected void applyReplacement(@Nonnull ColorTextureOverride override)
	{
		if (sizeMismatch(override))
		{
			return;
		}
		staged.applyTo(override);
	}

	public void replaceColorIndex(int index, short after)
	{
		staged.replaceColor(index, after);
		dirty.set(true);
	}

	public void replaceTextureIndex(int index, short after)
	{
		staged.replaceTexture(index, after);
		dirty.set(true);
	}

	@Nonnull
	public List<TextureReplacement> getTextureReplacements()
	{
		return staged.getTextureReplacements();
	}

	@Nonnull
	public List<ColorReplacement> getColorReplacements()
	{
		return getColorReplacementsFrom(staged);
	}

	public List<ColorReplacement> getDisplayedColorReplacements()
	{
		return getColorReplacementsFrom(snapshotState());
	}

	private List<ColorReplacement> getColorReplacementsFrom(GlamState state)
	{
		List<ColorReplacement> colorReplacements = new ArrayList<>();
		for (var stagedReplacement : state.getColorReplacements())
		{
			short modelColor = stagedReplacement.getModel();
			colorReplacements.add(new ColorReplacement(
				modelColor, primedItem.getOriginalColor(modelColor), stagedReplacement.getReplacement()));
		}
		return colorReplacements;
	}

	boolean isDirty()
	{
		return dirty.get();
	}

	boolean clearDirty()
	{
		return dirty.getAndSet(false);
	}

	GlamState snapshotState()
	{
		return staged.deepCopy(true);
	}
}

