package io.huze.glamourer.npc;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/// Track's the local player's follower and emits {@link FollowerChanged}.
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class FollowerTracker
{
	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;

	/// The world view the follower is in, -1 with no follower.
	@Getter
	private volatile int followerViewId = -1;

	/// The index within the world view; -1 with no follower.
	@Getter
	private volatile int followerIndex = -1;

	/// The follower's NPC id; -1 with no follower.
	@Getter
	private volatile int followerId = -1;

	private boolean refreshQueued;

	/// Waits a tick before reporting a despawn, so a pet that immediately respawns at a different
	/// index posts one event rather than two.
	private boolean changePending;

	public void start()
	{
		clientThread.invoke(this::refresh);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		maybeRefresh(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		maybeRefresh(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		maybeRefresh(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			clientThread.invoke(() -> {
				changePending = false;
				if (followerIndex != -1)
				{
					postEvent(-1, -1, -1);
				}
			});
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (changePending)
		{
			clientThread.invoke(() -> {
				changePending = false;
				if (client.getFollower() == null && followerIndex != -1)
				{
					postEvent(-1, -1, -1);
				}
			});
		}
	}

	private void maybeRefresh(NPC npc)
	{
		if (npc.getIndex() == followerIndex || npc == client.getFollower())
		{
			queueRefresh();
		}
	}

	private void queueRefresh()
	{
		if (!refreshQueued)
		{
			refreshQueued = true;
			clientThread.invokeAtTickEnd(() -> {
				refreshQueued = false;
				refresh();
			});
		}
	}

	private void refresh()
	{
		int viewId = -1;
		int index = -1;
		int id = -1;
		NPC follower = client.getFollower();
		if (follower != null)
		{
			viewId = follower.getWorldView().getId();
			index = follower.getIndex();
			id = follower.getId();
		}

		if (index == followerIndex && id == followerId && viewId == followerViewId)
		{
			changePending = false;
			return;
		}
		if (index == -1 && followerIndex != -1)
		{
			changePending = true;
			return;
		}
		changePending = false;
		postEvent(viewId, index, id);
	}

	/// Client thread only.
	private void postEvent(int viewId, int index, int id)
	{
		final boolean moved = followerIndex != index || this.followerViewId != viewId;
		final int oldIndex = moved ? followerIndex : -1;
		final int oldViewId = moved ? this.followerViewId : -1;
		followerIndex = index;
		followerId = id;
		this.followerViewId = viewId;
		log.debug("Follower changed {} {} {} {}", viewId, index, oldViewId, oldIndex);
		eventBus.post(new FollowerChanged(viewId, index, oldViewId, oldIndex));
	}
}

package io.huze.glamourer.npc;

import java.util.function.BooleanSupplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

@Slf4j
class GlamouredInstance extends RuneLiteObjectController
{
	private final Client client;
	private final NPC npc;
	private final NpcSheet npcSheet;
	private final BooleanSupplier realNpcDrawn;

	@Nullable
	private GlamouredModelData modelData;

	/// The glamour the model was built with
	@Nullable
	private NpcGlamour appliedGlamour;

	/// The last reason a frame failed to draw, logged once per change rather than per frame.
	@Nullable
	private String bailReason;
	private boolean isCenteredOnTile;

	GlamouredInstance(Client client, NPC npc, NpcSheet npcSheet, BooleanSupplier realNpcDrawn)
	{
		this.client = client;
		this.npc = npc;
		this.npcSheet = npcSheet;
		this.realNpcDrawn = realNpcDrawn;
		setRadius(0);
	}

	@Override
	@Nullable
	public Model getModel()
	{
		if (isCenteredOnTile && !realNpcDrawn.getAsBoolean())
		{
			return null;
		}
		if (modelData == null)
		{
			bail("no model");
			return null;
		}

		Model npcModel = npc.getModel();
		if (npcModel == null)
		{
			bail("actor model null");
			return null;
		}
		if (npcModel.getVerticesCount() < modelData.getVerticesCount())
		{
			bail("actor model vertex count mismatch");
			return null;
		}

		return modelData.copyPose(npcModel);
	}

	/// Return true if the director should suppress the actor
	boolean update(NpcGlamour glamour)
	{
		WorldView worldView = npc.getWorldView();
		LocalPoint location = npc.getLocalLocation();
		if (worldView == null || !worldView.contains(location))
		{
			setActive(false);
			return false;
		}

		if (!refreshModel(glamour))
		{
			return false;
		}

		LocalPoint tileCentre = LocalPoint.fromWorld(worldView, npc.getWorldLocation());
		isCenteredOnTile = tileCentre != null
			&& tileCentre.getX() == location.getX() && tileCentre.getY() == location.getY();
		setLocation(location, worldView.getPlane());
		setOrientation(npc.getCurrentOrientation());
		setZ(groundHeight(location, worldView));
		setActive(true);
		return true;
	}

	private boolean refreshModel(NpcGlamour glamour)
	{
		if (modelData != null && glamour.equals(appliedGlamour))
		{
			return true;
		}
		if (modelData == null)
		{
			modelData = GlamouredModelData.load(client, npcSheet, npc.getId());
			if (modelData == null)
			{
				return bail("nothing to build from");
			}
		}

		Model posed = npc.getModel();
		if (posed == null)
		{
			return bail("the actor has no model");
		}
		if (posed.getVerticesCount() < modelData.getVerticesCount())
		{
			return bail("the actor's model has " + posed.getVerticesCount()
				+ " vertices, the rebuild " + modelData.getVerticesCount());
		}

		modelData.applyGlamour(glamour);
		appliedGlamour = glamour;
		bailReason = null;
		return true;
	}

	private boolean bail(String reason)
	{
		if (!reason.equals(bailReason))
		{
			bailReason = reason;
			log.debug("Instance for \"{}\" not drawing: {}", npc.getName(), reason);
		}
		return false;
	}

	void setActive(boolean active)
	{
		if (active)
		{
			client.registerRuneLiteObject(this);
		}
		else
		{
			client.removeRuneLiteObject(this);
		}
	}

	private int groundHeight(LocalPoint location, WorldView worldView)
	{
		int height = Perspective.getFootprintTileHeight(client, location, worldView.getPlane(), npc.getFootprintSize());
		return height - npc.getAnimationHeightOffset();
	}
}

package io.huze.glamourer.npc;

import java.util.Arrays;
import javax.annotation.Nullable;
import net.runelite.api.Model;

final class GlamouredKind
{
	private final GlamouredModelData modelData;
	private int generation;
	private int frameCounter;
	@Nullable
	private int[][] glamouredLitFaces;
	@Nullable
	private int[][] modelFaces;
	@Nullable
	private int[][] lastWrittenFaces;
	@Nullable
	private short[] appliedTextures;

	GlamouredKind(GlamouredModelData modelData)
	{
		this.modelData = modelData;
	}

	boolean isPatchedInFrame(int frameCounter)
	{
		return this.frameCounter == frameCounter;
	}

	void setLastPatchedFrame(int frameCounter)
	{
		this.frameCounter = frameCounter;
	}

	boolean needsGlamourForGeneration(int generation)
	{
		return glamouredLitFaces == null || this.generation != generation;
	}

	boolean updateGlamour(NpcGlamour glamour, int generation)
	{
		modelData.applyGlamour(glamour);
		Model lit = modelData.light();
		if (lit == null)
		{
			return false;
		}
		glamouredLitFaces = GlamouredModelData.getFaceColorsOf(lit);
		this.generation = generation;
		return true;
	}

	void apply(Model live)
	{
		int[][] target = GlamouredModelData.getFaceColorsOf(live);
		if (this.modelFaces != null && this.modelFaces[0] == target[0] && lastWrittenFaces == glamouredLitFaces)
		{
			return;
		}
		final int[][] original = modelData.getOriginalLitColors();
		final int n = original[0].length;
		for (int i = 1; i < target.length; i++)
		{
			if (target[i].length < n)
			{
				return;
			}
		}
		if (!startsWith(target[0], original[0])
			&& (lastWrittenFaces == null || !startsWith(target[0], lastWrittenFaces[0])))
		{
			return;
		}
		for (int i = 0; i < target.length; i++)
		{
			System.arraycopy(glamouredLitFaces[i], 0, target[i], 0, n);
		}
		this.modelFaces = target;
		lastWrittenFaces = glamouredLitFaces;
		applyTextures(live);
	}

	private void applyTextures(Model live)
	{
		short[] target = live.getFaceTextures();
		short[] glamoured = modelData.getFaceTextures();
		if (target == null || glamoured == null)
		{
			return;
		}
		System.arraycopy(glamoured, 0, target, 0, Math.min(glamoured.length, target.length));
		appliedTextures = target;
	}

	boolean revertIfNotPatched(int frame)
	{
		if (frameCounter == frame)
		{
			return false;
		}
		revert();
		return true;
	}

	void revert()
	{
		if (modelFaces != null && lastWrittenFaces != null && startsWith(modelFaces[0], lastWrittenFaces[0]))
		{
			int[][] original = modelData.getOriginalLitColors();
			for (int i = 0; i < original.length; i++)
			{
				System.arraycopy(original[i], 0, modelFaces[i], 0, original[i].length);
			}
			short[] originalTextures = modelData.getOriginalTextures();
			if (appliedTextures != null && originalTextures != null)
			{
				System.arraycopy(originalTextures, 0, appliedTextures, 0,
					Math.min(originalTextures.length, appliedTextures.length));
			}
		}
		modelFaces = null;
		lastWrittenFaces = null;
		appliedTextures = null;
	}

	private static boolean startsWith(int[] live, int[] expected)
	{
		return live.length >= expected.length
			&& Arrays.equals(live, 0, expected.length, expected, 0, expected.length);
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.color.Colors;
import io.huze.glamourer.model.NpcModel;
import javax.annotation.Nullable;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

final class GlamouredModelData
{
	private final NpcModel npcModel;
	private final ModelData data;
	private final short[] originalColors;
	@Nullable
	private final short[] originalTextures;
	@Getter
	private final int[][] originalLitColors;

	private GlamouredModelData(NpcModel npcModel, int[][] originalLitColors)
	{
		this.npcModel = npcModel;
		this.data = npcModel.getData();
		this.originalColors = data.getFaceColors().clone();
		this.originalTextures = data.getFaceTextures() != null ? data.getFaceTextures().clone() : null;
		this.originalLitColors = originalLitColors;
	}

	@Nullable
	static GlamouredModelData load(Client client, NpcSheet npcSheet, int npcId)
	{
		NpcModel npcModel = NpcModel.load(client, npcSheet, npcId);
		if (npcModel == null)
		{
			return null;
		}

		ModelData data = npcModel.getData();
		data.cloneVertices()
			.cloneTransparencies();

		Model originalLit = npcModel.getLighting().light(data);
		if (originalLit == null)
		{
			return null;
		}
		return new GlamouredModelData(npcModel, getFaceColorsOf(originalLit));
	}

	void applyGlamour(NpcGlamour glamour)
	{
		System.arraycopy(originalColors, 0, data.getFaceColors(), 0, originalColors.length);
		short[] textures = data.getFaceTextures();
		if (textures != null && originalTextures != null)
		{
			System.arraycopy(originalTextures, 0, textures, 0, originalTextures.length);
		}

		short[] from = new short[countChanged(glamour)];
		short[] to = new short[from.length];
		int next = 0;
		for (ColorReplacement replacement : glamour.getColors())
		{
			if (replacement.hasChanged())
			{
				from[next] = npcModel.getColorAfterComposition(replacement.getModel());
				to[next] = replacement.getReplacement();
				next++;
			}
		}
		Colors.breakColorChains(from, to);
		for (int i = 0; i < from.length; i++)
		{
			data.recolor(from[i], to[i]);
		}

		glamour.applyTextures(textures);
	}

	@Nullable
	Model light()
	{
		return npcModel.getLighting().light(data);
	}

	@Nullable
	Model copyPose(Model posed)
	{
		final int count = data.getVerticesCount();
		System.arraycopy(posed.getVerticesX(), 0, data.getVerticesX(), 0, count);
		System.arraycopy(posed.getVerticesY(), 0, data.getVerticesY(), 0, count);
		System.arraycopy(posed.getVerticesZ(), 0, data.getVerticesZ(), 0, count);

		byte[] src = posed.getFaceTransparencies();
		byte[] dst = data.getFaceTransparencies();
		if (src != null && dst != null)
		{
			System.arraycopy(src, 0, dst, 0, Math.min(src.length, dst.length));
		}
		return light();
	}

	int getVerticesCount()
	{
		return data.getVerticesCount();
	}

	@Nullable
	short[] getFaceTextures()
	{
		return data.getFaceTextures();
	}

	@Nullable
	short[] getOriginalTextures()
	{
		return originalTextures;
	}

	static int[][] getFaceColorsOf(Model model)
	{
		return new int[][]{model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3()};
	}

	private static int countChanged(NpcGlamour glamour)
	{
		int changed = 0;
		for (ColorReplacement replacement : glamour.getColors())
		{
			if (replacement.hasChanged())
			{
				changed++;
			}
		}
		return changed;
	}
}

package io.huze.glamourer.npc;

import java.util.Objects;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/// Tracks the owner of the house the player is currently in.
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class HouseTracker
{
	private final Client client;

	/// Standardized name if visiting or null if local player's house / not in a house.
	@Getter
	@Nullable
	private volatile String currentOwnerName;
	/// Standardized name of who might be visited based on the name dialog.
	@Nullable
	private String pendingOwnerName;
	private boolean enteringFromBoard;
	private boolean enteringHouse;

	/// The last house entered from the board, which is what its "Visit-Last" returns to.
	@Nullable
	private String lastBoardOwner;

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
			case LOGGED_IN:
				final String entered = consumePendingOwner();
				if (!client.getTopLevelWorldView().isInstance())
				{
					setOwner(null);
				}
				else if (entered != null && enteringHouse)
				{
					setOwner(entered);
				}
				if (event.getGameState() == GameState.LOGGED_IN)
				{
					enteringHouse = false;
				}
				break;
			case LOGIN_SCREEN:
			case HOPPING:
				pendingOwnerName = null;
				enteringFromBoard = false;
				enteringHouse = false;
				lastBoardOwner = null;
				setOwner(null);
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (event.getIndex() == VarClientID.LAST_NAMEDIALOG)
		{
			String name = client.getVarcStrValue(VarClientID.LAST_NAMEDIALOG);
			pendingOwnerName = name == null || name.isBlank() ? null : Text.standardize(name);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() == InterfaceID.PohBoard.BUTTON)
		{
			enteringFromBoard = true;
		}
		else if ("Visit-Last".equalsIgnoreCase(event.getMenuOption()))
		{
			enteringFromBoard = true;
			pendingOwnerName = lastBoardOwner;
		}
	}

	@Nullable
	private String consumePendingOwner()
	{
		String owner = pendingOwnerName;
		if (owner != null && enteringFromBoard)
		{
			lastBoardOwner = owner;
		}
		pendingOwnerName = null;
		enteringFromBoard = false;
		return owner;
	}

	private void setOwner(@Nullable String owner)
	{
		if (!Objects.equals(owner, currentOwnerName))
		{
			currentOwnerName = owner;
			log.debug("house: {}", owner == null ? "none" : owner + "'s");
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.POH_LOADING)
		{
			enteringHouse = true;
		}
	}
}

package io.huze.glamourer.npc;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
class InstanceDirector
{
	private final Client client;
	private final EventBus eventBus;
	private final RenderCallbackManager renderCallbackManager;
	private final NpcSheet npcSheet;
	private final Map<NPC, GlamouredInstance> instances = new IdentityHashMap<>();
	/// Actors whose draws should be suppressed
	private final Set<Actor> hidden = Collections.newSetFromMap(new IdentityHashMap<>());
	/// Actors whose draws were actually suppressed
	private final Set<Actor> drawnByClient = Collections.newSetFromMap(new IdentityHashMap<>());

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			if (hidden.isEmpty())
			{
				return true;
			}
			Actor actor = getActorBehind(object);
			if (actor instanceof NPC && hidden.contains(actor))
			{
				drawnByClient.add(actor);
				return false;
			}
			return true;
		}
	};

	void startUp()
	{
		eventBus.register(this);
		renderCallbackManager.register(renderCallback);
	}

	void shutDown()
	{
		eventBus.unregister(this);
		renderCallbackManager.unregister(renderCallback);
	}

	void beginFrame()
	{
		hidden.clear();
		drawnByClient.clear();
	}

	void drawInstanceFor(NPC npc, NpcGlamour glamour)
	{
		GlamouredInstance instance = instances.get(npc);
		if (instance == null)
		{
			instance = new GlamouredInstance(client, npc, npcSheet, () -> drawnByClient.contains(npc));
			instances.put(npc, instance);
		}

		if (instance.update(glamour))
		{
			hidden.add(npc);
		}
	}

	void endFrame()
	{
		for (Map.Entry<NPC, GlamouredInstance> entry : instances.entrySet())
		{
			if (!hidden.contains(entry.getKey()))
			{
				entry.getValue().setActive(false);
			}
		}
	}

	void hideAllInstances()
	{
		for (GlamouredInstance instance : instances.values())
		{
			instance.setActive(false);
		}
	}

	void destroyAllInstances()
	{
		hidden.clear();
		drawnByClient.clear();
		hideAllInstances();
		instances.clear();
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		GlamouredInstance instance = instances.remove(event.getNpc());
		if (instance != null)
		{
			instance.setActive(false);
		}
		hidden.remove(event.getNpc());
	}

	@Nullable
	private Actor getActorBehind(TileObject object)
	{
		if (object instanceof GameObject)
		{
			Renderable renderable = ((GameObject) object).getRenderable();
			if (renderable instanceof Actor)
			{
				return (Actor) renderable;
			}
		}
		return null;
	}
}

package io.huze.glamourer.npc;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;

/**
 * Patches the client's lit model in place without copying colors.
 * This is the same technique that CG recolour plugin uses to modify NPC colors without using RLOs.
 */
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
class KindDirector
{
	private final Client client;
	private final NpcSheet npcSheet;

	/// Holds only the kinds patched this frame; {@link #endFrame} drops the rest.
	private final Map<Integer, GlamouredKind> kinds = new HashMap<>();
	private int frameCounter;
	/// Bumped when any kind glamour changes, so existing kinds reglamour lazily.
	private int generation;

	void beginFrame()
	{
		frameCounter++;
	}

	void applyKindGlamour(NPC npc, NpcGlamour glamour)
	{
		final int npcId = npc.getId();
		GlamouredKind kind = kinds.get(npcId);
		if (kind != null && kind.isPatchedInFrame(frameCounter))
		{
			return;
		}
		if (kind == null)
		{
			var modelData = GlamouredModelData.load(client, npcSheet, npcId);
			if (modelData == null)
			{
				return;
			}
			kind = new GlamouredKind(modelData);
			kinds.put(npcId, kind);
		}
		kind.setLastPatchedFrame(frameCounter);

		Model live = npc.getModel();
		if (live == null)
		{
			return;
		}
		if (kind.needsGlamourForGeneration(generation) && !kind.updateGlamour(glamour, generation))
		{
			return;
		}
		kind.apply(live);
	}

	void endFrame()
	{
		kinds.values().removeIf(kind -> kind.revertIfNotPatched(frameCounter));
	}

	void restoreAllOriginals()
	{
		for (GlamouredKind kind : kinds.values())
		{
			kind.revert();
		}
		kinds.clear();
	}

	void invalidateGlamours()
	{
		++generation;
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.texture.TextureReplacement;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.annotation.Nullable;

/**
 * Immutable NPC glamour
 */
final class NpcGlamour
{
	/// The client's marker for a face carrying no texture.
	private static final short NO_TEXTURE = -1;

	private static final NpcGlamour EMPTY = new NpcGlamour(List.of(), List.of());

	private final List<ColorReplacement> colors;
	private final List<TextureReplacement> textures;

	/// For simple equality comparison
	private final int[] packed;

	private NpcGlamour(List<ColorReplacement> colors, List<TextureReplacement> textures)
	{
		this.colors = colors;
		this.textures = textures;
		packed = new int[1 + colors.size() + textures.size()];
		packed[0] = colors.size();
		int next = 1;
		for (ColorReplacement color : colors)
		{
			packed[next++] = pack(color.getOriginal(), color.getReplacement());
		}
		for (TextureReplacement texture : textures)
		{
			packed[next++] = pack(texture.getOriginal(), texture.getReplacement());
		}
	}

	static NpcGlamour empty()
	{
		return EMPTY;
	}

	static NpcGlamour of(@Nullable List<ColorReplacement> colors, @Nullable List<TextureReplacement> textures)
	{
		if (isNullOrEmpty(colors) && isNullOrEmpty(textures))
		{
			return EMPTY;
		}
		return new NpcGlamour(copyColors(colors), copyTextures(textures));
	}

	private static List<ColorReplacement> copyColors(@Nullable List<ColorReplacement> colors)
	{
		if (isNullOrEmpty(colors))
		{
			return List.of();
		}
		List<ColorReplacement> copies = new ArrayList<>(colors.size());
		for (ColorReplacement color : colors)
		{
			copies.add(new ColorReplacement(
				color.getModel(), color.getOriginal(), color.getReplacement()));
		}
		return copies;
	}

	private static List<TextureReplacement> copyTextures(@Nullable List<TextureReplacement> textures)
	{
		if (isNullOrEmpty(textures))
		{
			return List.of();
		}
		List<TextureReplacement> copies = new ArrayList<>(textures.size());
		for (TextureReplacement texture : textures)
		{
			copies.add(new TextureReplacement(texture.getOriginal(), texture.getReplacement()));
		}
		return copies;
	}

	private static boolean isNullOrEmpty(@Nullable List<?> list)
	{
		return list == null || list.isEmpty();
	}

	boolean isEmpty()
	{
		return colors.isEmpty() && textures.isEmpty();
	}

	List<ColorReplacement> getColors()
	{
		return colors;
	}

	void applyTextures(@Nullable short[] faceTextures)
	{
		if (faceTextures == null || textures.isEmpty())
		{
			return;
		}
		for (int face = 0; face < faceTextures.length; face++)
		{
			final short current = faceTextures[face];
			if (current == NO_TEXTURE)
			{
				continue;
			}
			for (TextureReplacement texture : textures)
			{
				if (texture.hasChanged() && texture.getOriginal() == current
					&& texture.getReplacement() != NO_TEXTURE)
				{
					faceTextures[face] = texture.getReplacement();
					break;
				}
			}
		}
	}

	@Override
	public boolean equals(Object other)
	{
		return other instanceof NpcGlamour && Arrays.equals(packed, ((NpcGlamour) other).packed);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(packed);
	}

	private static int pack(short original, short replacement)
	{
		return (original << 16) | (replacement & 0xFFFF);
	}
}

package io.huze.glamourer.npc;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.WorldView;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class NpcGlamourer
{
	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final KindDirector kindDirector;
	private final InstanceDirector instanceDirector;

	private final Map<Integer, NpcGlamour> kindGlamours = new HashMap<>();

	@Setter(AccessLevel.PACKAGE)
	private Map<NpcInstanceKey, NpcGlamour> instanceGlamours = Map.of();

	private boolean running;

	public void startUp()
	{
		if (running)
		{
			return;
		}
		running = true;
		eventBus.register(this);
		instanceDirector.startUp();
	}

	public void shutDown()
	{
		if (!running)
		{
			return;
		}
		running = false;
		eventBus.unregister(this);
		instanceDirector.shutDown();
		clientThread.invoke(() -> {
			kindGlamours.clear();
			instanceGlamours = Map.of();
			destroyAll();
		});
	}

	void setKindGlamour(int npcId, NpcGlamour glamour)
	{
		if (glamour.isEmpty())
		{
			clearKindGlamour(npcId);
			return;
		}
		if (glamour.equals(kindGlamours.get(npcId)))
		{
			return;
		}
		kindGlamours.put(npcId, glamour);
		invalidatePatches();
	}

	private void clearKindGlamour(int npcId)
	{
		if (kindGlamours.remove(npcId) != null)
		{
			invalidatePatches();
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		instanceDirector.beginFrame();
		kindDirector.beginFrame();
		{
			final boolean idle = kindGlamours.isEmpty() && instanceGlamours.isEmpty();
			if (idle || client.getGameState() != GameState.LOGGED_IN)
			{
				instanceDirector.hideAllInstances();
				kindDirector.restoreAllOriginals();
				return;
			}
			glamourNpcsInView(client.getTopLevelWorldView());
		}
		instanceDirector.endFrame();
		kindDirector.endFrame();
	}

	private void glamourNpcsInView(WorldView worldView)
	{
		final int viewId = worldView.getId();
		for (NPC npc : worldView.npcs())
		{
			if (npc == null)
			{
				continue;
			}
			final int npcId = npc.getId();

			NpcGlamour glamour = null;
			boolean isInstanceGlamour = true;
			if (!instanceGlamours.isEmpty())
			{
				glamour = instanceGlamours.get(new NpcInstanceKey(viewId, npc.getIndex(), npcId));
			}
			if (glamour == null)
			{
				isInstanceGlamour = false;
				glamour = kindGlamours.get(npcId);
			}
			if (glamour == null)
			{
				continue;
			}

			if (isInstanceGlamour)
			{
				instanceDirector.drawInstanceFor(npc, glamour);
			}
			else
			{
				kindDirector.applyKindGlamour(npc, glamour);
			}
		}

		for (WorldView nested : worldView.worldViews())
		{
			if (nested != null)
			{
				glamourNpcsInView(nested);
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
			case HOPPING:
			case CONNECTION_LOST:
			case LOGIN_SCREEN:
				destroyAll();
				break;
			default:
				break;
		}
	}

	private void destroyAll()
	{
		kindDirector.restoreAllOriginals();
		instanceDirector.destroyAllInstances();
	}

	private void invalidatePatches()
	{
		clientThread.invoke(kindDirector::invalidateGlamours);
	}
}

package io.huze.glamourer.npc;

class NpcInstanceKey
{
	private final int viewId;
	private final int npcIndex;
	private final int npcId;

	NpcInstanceKey(int viewId, int npcIndex, int npcId)
	{
		this.viewId = viewId;
		this.npcIndex = npcIndex;
		this.npcId = npcId;
	}

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof NpcInstanceKey))
		{
			return false;
		}
		NpcInstanceKey key = (NpcInstanceKey) other;
		return viewId == key.viewId && npcIndex == key.npcIndex && npcId == key.npcId;
	}

	@Override
	public int hashCode()
	{
		return 31 * (31 * viewId + npcIndex) + npcId;
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.Sheet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;

@Singleton
public class NpcSheet extends Sheet<int[]>
{
	public static final class Lighting
	{
		static final Lighting DEFAULT = new Lighting(0, 0);

		@Getter
		private final int ambient;
		@Getter
		private final int contrast;

		private Lighting(int ambient, int contrast)
		{
			this.ambient = ambient;
			this.contrast = contrast;
		}
	}

	private volatile Map<Integer, Lighting> lightingByNpcId = Map.of();

	public NpcSheet()
	{
		super("npc_sheet.csv", new String[]{"id", "ambient", "contrast"},
			cols -> new int[]{Integer.parseInt(cols[0]), Integer.parseInt(cols[1]), Integer.parseInt(cols[2])});
	}

	public Lighting getLighting(int npcId)
	{
		return lightingByNpcId.getOrDefault(npcId, Lighting.DEFAULT);
	}

	@Override
	protected void load(List<int[]> rows)
	{
		Map<Integer, Lighting> lighting = new HashMap<>();
		for (int[] row : rows)
		{
			if (row[1] != 0 || row[2] != 0)
			{
				lighting.put(row[0], new Lighting(row[1], row[2]));
			}
		}
		this.lightingByNpcId = lighting;
	}
}

package io.huze.glamourer.npc;

import io.huze.glamourer.glam.GlamourData;
import io.huze.glamourer.glam.GlamourEngine;
import io.huze.glamourer.item.PetSheet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class PetGlamourSync
{
	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final GlamourEngine glamourEngine;
	private final NpcGlamourer npcGlamourer;
	private final PetSheet petSheet;
	private final FollowerTracker followerTracker;
	private final HouseTracker houseTracker;

	/// Member pet glamours keyed by party member id. Client thread only.
	private final Map<Long, PlayerPetGlamours> partyMembers = new HashMap<>();

	/// Is NPC ID a non-follower pet (PoH menagerie). Client thread only.
	private final Map<Integer, Boolean> nonFollowerPetByNpcId = new HashMap<>();

	/// Is end-of-tick glamour sync queued. Client thread only.
	private boolean syncQueued;

	public void startUp()
	{
		eventBus.register(houseTracker);
		eventBus.register(followerTracker);
		eventBus.register(this);
		followerTracker.start();
	}

	public void shutDown()
	{
		eventBus.unregister(this);
		eventBus.unregister(followerTracker);
		eventBus.unregister(houseTracker);
	}

	/// Client thread only.
	public void updatePartyMember(long memberId, String standardizedName,
		Map<Integer, GlamourData> itemGlamours, int followerViewId, int followerIndex)
	{
		partyMembers.put(memberId,
			new PlayerPetGlamours(standardizedName, filterNonPetGlamours(itemGlamours), followerViewId, followerIndex));
		queueSync();
	}

	/// Client thread only.
	public void removePartyMember(long memberId)
	{
		if (partyMembers.remove(memberId) != null)
		{
			queueSync();
		}
	}

	/// Client thread only.
	public void clearPartyMembers()
	{
		if (!partyMembers.isEmpty())
		{
			partyMembers.clear();
			queueSync();
		}
	}

	/// Glamours for visited PoH owner's Menagerie pets
	/// We don't actually know what pets are in their menagerie, so we must return all pet glamours.
	private Map<Integer, NpcGlamour> getVisitedOwnerGlamours()
	{
		String houseOwner = houseTracker.getCurrentOwnerName();
		if (houseOwner != null)
		{
			for (PlayerPetGlamours member : partyMembers.values())
			{
				if (houseOwner.equals(member.standardizedName))
				{
					return member.petGlamours;
				}
			}
		}
		return Map.of();
	}

	private Map<Integer, NpcGlamour> filterNonPetGlamours(Map<Integer, GlamourData> itemGlamours)
	{
		Map<Integer, List<Integer>> pets = petSheet.getNpcsByItemId();
		Map<Integer, NpcGlamour> glamours = new HashMap<>();
		itemGlamours.forEach((itemId, data) -> {
			if (pets.containsKey(itemId))
			{
				NpcGlamour glamour = NpcGlamour.of(data.getColorReplacements(), data.getTextureReplacements());
				if (!glamour.isEmpty())
				{
					glamours.put(itemId, glamour);
				}
			}
		});
		return glamours;
	}

	public void sync()
	{
		var petItemsToNpcIds = petSheet.getNpcsByItemId();
		Map<Integer, NpcGlamour> ours = getOurGlamours(petItemsToNpcIds.keySet());
		syncKinds(petItemsToNpcIds, ours);
		syncInstances(petItemsToNpcIds, ours);
	}

	private Map<Integer, NpcGlamour> getOurGlamours(Set<Integer> itemIds)
	{
		Map<Integer, NpcGlamour> glamours = new HashMap<>();
		for (GlamourData data : glamourEngine.getGlamourSnapshotForItems(itemIds))
		{
			Integer itemId = data.getItemId();
			if (itemId != null)
			{
				glamours.put(itemId, NpcGlamour.of(data.getColorReplacements(), data.getTextureReplacements()));
			}
		}
		return glamours;
	}

	private void syncKinds(Map<Integer, List<Integer>> petItemsToNpcIds, Map<Integer, NpcGlamour> ourGlamours)
	{
		final var ownerGlamours = getVisitedOwnerGlamours();
		for (var petItemsToNpcId : petItemsToNpcIds.entrySet())
		{
			final int itemId = petItemsToNpcId.getKey();
			NpcGlamour ours = ourGlamours.getOrDefault(itemId, NpcGlamour.empty());
			NpcGlamour placed = ownerGlamours.getOrDefault(itemId, ours);
			NpcGlamour follower = glamourEngine.isGlobal(itemId) ? ours : NpcGlamour.empty();
			for (int npcId : petItemsToNpcId.getValue())
			{
				NpcGlamour kindGlamour = placed == follower
					? placed
					: isNonFollowerPet(npcId) ? placed : follower;
				npcGlamourer.setKindGlamour(npcId, kindGlamour);
			}
		}
	}

	private void syncInstances(Map<Integer, List<Integer>> petItemsToNpcIds, Map<Integer, NpcGlamour> ourGlamours)
	{
		final int ourViewId = followerTracker.getFollowerViewId();
		final int ourIndex = followerTracker.getFollowerIndex();

		Map<NpcInstanceKey, NpcGlamour> instances = new HashMap<>();
		for (PlayerPetGlamours member : partyMembers.values())
		{
			if (member.followerIndex == -1
				|| (member.followerIndex == ourIndex && member.followerViewId == ourViewId))
			{
				continue;
			}
			member.petGlamours.forEach((itemId, glamour) ->
				addInstance(instances, member.followerViewId, member.followerIndex,
					petItemsToNpcIds.getOrDefault(itemId, List.of()), glamour));
		}

		if (ourIndex != -1)
		{
			final int itemId = petSheet.getItemId(followerTracker.getFollowerId());
			NpcGlamour ours = itemId == -1 || glamourEngine.isGlobal(itemId)
				? NpcGlamour.empty()
				: ourGlamours.getOrDefault(itemId, NpcGlamour.empty());
			addInstance(instances, ourViewId, ourIndex, petItemsToNpcIds.getOrDefault(itemId, List.of()), ours);
		}

		npcGlamourer.setInstanceGlamours(instances);
	}

	private static void addInstance(Map<NpcInstanceKey, NpcGlamour> instances, int viewId,
		int npcIndex, List<Integer> npcIds, NpcGlamour glamour)
	{
		if (glamour.isEmpty())
		{
			return;
		}
		for (int npcId : npcIds)
		{
			instances.put(new NpcInstanceKey(viewId, npcIndex, npcId), glamour);
		}
	}

	private boolean isNonFollowerPet(int npcId)
	{
		return nonFollowerPetByNpcId.computeIfAbsent(npcId, id -> {
			NPCComposition composition = client.getNpcDefinition(id);
			return composition != null && !composition.isFollower();
		});
	}

	public void queueSync()
	{
		if (syncQueued)
		{
			return;
		}
		syncQueued = true;
		clientThread.invokeAtTickEnd(() -> {
			syncQueued = false;
			sync();
		});
	}

	private void queueSyncFor(NPC npc)
	{
		if (petSheet.getItemId(npc.getId()) != -1 && isNonFollowerPet(npc.getId()))
		{
			queueSync();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		queueSyncFor(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		queueSyncFor(event.getNpc());
	}

	@Subscribe
	public void onFollowerChanged(FollowerChanged event)
	{
		// Immediate sync instead of queued to prevent color pop-in
		sync();
	}

}

