package io.huze.glamourer.render;

import io.huze.glamourer.color.Shade;
import io.huze.glamourer.texture.SamplableTextureProvider;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import javax.annotation.Nonnull;

/// Creator's Kit's triangle fill with a depth buffer per render priority, as in the GPU plugin.
/// Translucent faces skip the depth write.
/// Buffers are re-used for each render.
final class ModelRasterizer
{
	private static final int OPAQUE = 0xFF000000;
	private static final int OPAQUE_ALPHA = 255;
	private static final int HOLE = 0;
	private static final int[] NO_PIXELS = {};
	private static final float[] NO_DEPTHS = {};
	private static final byte[] NO_PRIORITIES = {};
	private static final int[] NO_TAGS = {};
	private static final float EMPTY_INVERSE_DEPTH = 0;
	/// The GPU plugin depth tests 100/depth + bias/128.
	private static final double BIAS_UNITS_PER_INVERSE_DEPTH = 100 * 128;

	@Nonnull
	private final SamplableTextureProvider textureProvider;
	private int[] raster = NO_PIXELS;
	/// 1/depth, so nearer is larger.
	private float[] inverseDepths = NO_DEPTHS;
	private byte[] priorities = NO_PRIORITIES;
	private int[] regionTags = NO_TAGS;

	ModelRasterizer(@Nonnull SamplableTextureProvider textureProvider)
	{
		this.textureProvider = textureProvider;
	}

	@Nonnull
	ModelRegions draw(@Nonnull ProjectedModel projected, long cycle, @Nonnull BufferedImage target)
	{
		int pixelCount = draw(projected, cycle, target, false);
		return new ModelRegions(projected.rasterSize, Arrays.copyOf(regionTags, pixelCount));
	}

	void drawOutlined(@Nonnull ProjectedModel projected, long cycle, @Nonnull BufferedImage target)
	{
		draw(projected, cycle, target, true);
	}

	private int draw(@Nonnull ProjectedModel projected, long cycle, @Nonnull BufferedImage target, boolean outlined)
	{
		final RasterSize size = projected.rasterSize;
		int[] pixels = size.getImagePixels(target);
		int[] raster = size.getSupersample() == 1 ? pixels : getRaster(size.getRasterWidth() * size.getRasterHeight());
		int pixelCount = rasterize(projected, cycle, raster);
		if (outlined)
		{
			Outliner.drawIconOutline(raster, size);
		}
		if (raster != pixels)
		{
			size.downscale(raster, pixels);
		}
		return pixelCount;
	}

	private int rasterize(@Nonnull ProjectedModel projected, long cycle, @Nonnull int[] pixels)
	{
		final RasterSize size = projected.rasterSize;
		final int pixelCount = size.getRasterWidth() * size.getRasterHeight();
		Arrays.fill(pixels, 0, pixelCount, 0);
		if (inverseDepths.length < pixelCount)
		{
			inverseDepths = new float[pixelCount];
			priorities = new byte[pixelCount];
			regionTags = new int[pixelCount];
		}
		Arrays.fill(inverseDepths, 0, pixelCount, EMPTY_INVERSE_DEPTH);
		Arrays.fill(priorities, 0, pixelCount, (byte) 0);
		Arrays.fill(regionTags, 0, pixelCount, 0);
		for (int face = 0; face < projected.faceCount; face++)
		{
			fill(projected, face, cycle, pixels, inverseDepths, priorities, regionTags);
		}
		return pixelCount;
	}

	@Nonnull
	private int[] getRaster(int pixelCount)
	{
		if (raster.length < pixelCount)
		{
			raster = new int[pixelCount];
		}
		return raster;
	}

	private void fill(@Nonnull ProjectedModel model, int face, long cycle, @Nonnull int[] pixels,
					  @Nonnull float[] depths, @Nonnull byte[] priorities, @Nonnull int[] tags)
	{
		double area = model.getWindingArea(face);
		if (!(area > 0))
		{
			return;
		}
		int corner = face * 3;
		double x1 = model.x[corner];
		double y1 = model.y[corner];
		double x2 = model.x[corner + 1];
		double y2 = model.y[corner + 1];
		double x3 = model.x[corner + 2];
		double y3 = model.y[corner + 2];
		int color1 = model.colors[corner];
		int color2 = model.colors[corner + 1];
		int color3 = model.colors[corner + 2];

		int width = model.rasterSize.getRasterWidth();
		int height = model.rasterSize.getRasterHeight();
		int minX = (int) Math.max(0, Math.ceil(Math.min(x1, Math.min(x2, x3))));
		int maxX = (int) Math.min(width - 1, Math.floor(Math.max(x1, Math.max(x2, x3))));
		int minY = (int) Math.max(0, Math.ceil(Math.min(y1, Math.min(y2, y3))));
		int maxY = (int) Math.min(height - 1, Math.floor(Math.max(y1, Math.max(y2, y3))));

		double step1 = (y3 - y2) / area;
		double step2 = (y1 - y3) / area;
		double step3 = (y2 - y1) / area;
		int alpha = model.alphas[face];
		boolean blend = alpha != OPAQUE_ALPHA;
		byte priority = model.priorities[face];
		int tag = ModelRegions.tag(model.colorIndices[face], model.textureIndices[face]);
		// Bias affects only the depth test.
		double nearness = 1 + model.biases[face] / BIAS_UNITS_PER_INVERSE_DEPTH;

		// Perspective correct: 1/depth and uv/depth interpolate linearly.
		double inverseDepth1 = 1 / model.depth[corner];
		double inverseDepth2 = 1 / model.depth[corner + 1];
		double inverseDepth3 = 1 / model.depth[corner + 2];
		var texture = model.textures[face] == ProjectedModel.UNTEXTURED ? null : textureProvider.get(model.textures[face]);
		double columnOverDepth1 = 0;
		double columnOverDepth2 = 0;
		double columnOverDepth3 = 0;
		double rowOverDepth1 = 0;
		double rowOverDepth2 = 0;
		double rowOverDepth3 = 0;
		if (texture != null)
		{
			int size = texture.getSize();
			columnOverDepth1 = model.us[corner] * size * inverseDepth1;
			columnOverDepth2 = model.us[corner + 1] * size * inverseDepth2;
			columnOverDepth3 = model.us[corner + 2] * size * inverseDepth3;
			rowOverDepth1 = model.vs[corner] * size * inverseDepth1;
			rowOverDepth2 = model.vs[corner + 1] * size * inverseDepth2;
			rowOverDepth3 = model.vs[corner + 2] * size * inverseDepth3;
		}

		for (int y = minY; y <= maxY; y++)
		{
			double weight1 = ((y - y3) * (x2 - x3) + (y2 - y3) * (x3 - minX)) / area;
			double weight2 = ((y - y1) * (x3 - x1) + (y3 - y1) * (x1 - minX)) / area;
			double weight3 = ((y - y2) * (x1 - x2) + (y1 - y2) * (x2 - minX)) / area;
			boolean entered = false;
			for (int x = minX; x <= maxX; x++, weight1 += step1, weight2 += step2, weight3 += step3)
			{
				if (weight1 < 0 || weight2 < 0 || weight3 < 0)
				{
					if (entered)
					{
						break;
					}
					continue;
				}
				entered = true;

				int index = y * width + x;
				double inverseDepth = weight1 * inverseDepth1 + weight2 * inverseDepth2 + weight3 * inverseDepth3;
				float biasedInverseDepth = (float) (inverseDepth * nearness);
				// Ties go to the later face
				if (priorities[index] == priority && biasedInverseDepth < depths[index])
				{
					continue;
				}

				int rgb;
				if (texture == null)
				{
					rgb = blendColors(color1, color2, color3, weight1, weight2, weight3);
				}
				else
				{
					double depthScale = 1 / inverseDepth;
					int column = (int) Math.floor(
						(weight1 * columnOverDepth1 + weight2 * columnOverDepth2 + weight3 * columnOverDepth3) * depthScale);
					int row = (int) Math.floor(
						(weight1 * rowOverDepth1 + weight2 * rowOverDepth2 + weight3 * rowOverDepth3) * depthScale);
					int texel = texture.sample(column, row, cycle);
					if (texel == HOLE)
					{
						continue;
					}
					rgb = shadeTexel(texel, (int) (color1 * weight1 + color2 * weight2 + color3 * weight3));
				}
				tags[index] = tag;
				if (blend)
				{
					pixels[index] = blend(rgb, alpha, pixels[index]);
				}
				else
				{
					pixels[index] = OPAQUE | rgb;
					depths[index] = biasedInverseDepth;
					priorities[index] = priority;
				}
			}
		}
	}

	private static int blendColors(int rgb1, int rgb2, int rgb3, double weight1, double weight2, double weight3)
	{
		int red = (int) (((rgb1 >> 16) & 0xFF) * weight1 + ((rgb2 >> 16) & 0xFF) * weight2 + ((rgb3 >> 16) & 0xFF) * weight3);
		int green = (int) (((rgb1 >> 8) & 0xFF) * weight1 + ((rgb2 >> 8) & 0xFF) * weight2 + ((rgb3 >> 8) & 0xFF) * weight3);
		int blue = (int) ((rgb1 & 0xFF) * weight1 + (rgb2 & 0xFF) * weight2 + (rgb3 & 0xFF) * weight3);
		int rgb = (red << 16) | (green << 8) | blue;
		return rgb == HOLE ? 1 : rgb;
	}

	private static int shadeTexel(int texel, int shade)
	{
		int red = Shade.scale((texel >> 16) & 0xFF, shade);
		int green = Shade.scale((texel >> 8) & 0xFF, shade);
		int blue = Shade.scale(texel & 0xFF, shade);
		int shaded = (red << 16) | (green << 8) | blue;
		return shaded == HOLE ? 1 : shaded;
	}

	private static int blend(int sourceRgb, int sourceAlpha, int destinationArgb)
	{
		int destinationAlpha = (destinationArgb >>> 24) * (255 - sourceAlpha) / 255;
		int alpha = sourceAlpha + destinationAlpha;
		if (alpha == 0)
		{
			return 0;
		}
		int red = (((sourceRgb >> 16) & 0xFF) * sourceAlpha + ((destinationArgb >> 16) & 0xFF) * destinationAlpha) / alpha;
		int green = (((sourceRgb >> 8) & 0xFF) * sourceAlpha + ((destinationArgb >> 8) & 0xFF) * destinationAlpha) / alpha;
		int blue = ((sourceRgb & 0xFF) * sourceAlpha + (destinationArgb & 0xFF) * destinationAlpha) / alpha;
		return (alpha << 24) | (red << 16) | (green << 8) | blue;
	}
}

package io.huze.glamourer.render;

import java.awt.image.BufferedImage;
import javax.annotation.Nonnull;

public final class ModelRegions
{
	public static final int NONE = -1;
	private static final int OUTLINE_ARGB = 0xFFFFFFFF;

	@Nonnull
	private final RasterSize size;
	/// Per raster pixel, the color index plus one in the low half and the texture index plus one in
	/// the high half, so a pixel showing nothing of the glamour is 0.
	@Nonnull
	private final int[] tags;

	ModelRegions(@Nonnull RasterSize size, @Nonnull int[] tags)
	{
		this.size = size;
		this.tags = tags;
	}

	static int tag(short colorIndex, short textureIndex)
	{
		return ((textureIndex + 1) << 16) | ((colorIndex + 1) & 0xFFFF);
	}

	private static int colorIndexOf(int tag)
	{
		return (tag & 0xFFFF) - 1;
	}

	private static int textureIndexOf(int tag)
	{
		return (tag >>> 16) - 1;
	}

	/// The index in the glamour of the color drawn at an image pixel, or [#NONE].
	public int getColorIndexAt(int imageX, int imageY)
	{
		return colorIndexOf(tagAt(imageX, imageY));
	}

	/// The index in the glamour of the texture drawn at an image pixel, or [#NONE].
	public int getTextureIndexAt(int imageX, int imageY)
	{
		return textureIndexOf(tagAt(imageX, imageY));
	}

	private int tagAt(int imageX, int imageY)
	{
		int supersample = size.getSupersample();
		int x = imageX * supersample + supersample / 2;
		int y = imageY * supersample + supersample / 2;
		if (imageX < 0 || imageY < 0 || x >= size.getRasterWidth() || y >= size.getRasterHeight())
		{
			return 0;
		}
		return tags[y * size.getRasterWidth() + x];
	}

	public void outline(@Nonnull RegionSelection selection, @Nonnull BufferedImage target)
	{
		int[] pixels = size.getImagePixels(target);
		boolean[] outside = new boolean[tags.length];
		for (int index = 0; index < outside.length; index++)
		{
			outside[index] = !selection.selects(colorIndexOf(tags[index]), textureIndexOf(tags[index]));
		}
		int[] raster = new int[tags.length];
		Outliner.paintEdge(raster, outside, size, OUTLINE_ARGB);
		size.downscale(raster, pixels);
	}
}

package io.huze.glamourer.render;

import io.huze.glamourer.item.ItemRenderSheet;
import io.huze.glamourer.texture.SamplableTextureProvider;
import io.huze.glamourer.texture.TextureAnimation;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Constants;

/// Executor thread only.
@Singleton
public final class ModelRenderer
{
	private static final int ICON_SUPERSAMPLE = 3;

	private final ModelProjector projector = new ModelProjector();
	private final ModelRasterizer rasterizer;

	@Inject
	public ModelRenderer(@Nonnull SamplableTextureProvider textureProvider)
	{
		this.rasterizer = new ModelRasterizer(textureProvider);
	}

	/// Scale of 1 is 36 x 32
	@Nonnull
	public static Dimension getIconSize(float scale)
	{
		return new Dimension(Math.round(Constants.ITEM_SPRITE_WIDTH * scale), Math.round(Constants.ITEM_SPRITE_HEIGHT * scale));
	}

	@Nonnull
	public ModelRegions drawOrbit(@Nonnull PosedModel model, @Nonnull OrbitView view, int supersample,
								  @Nonnull BufferedImage target)
	{
		var rasterSize = new RasterSize(target.getWidth(), target.getHeight(), supersample);
		var snapshot = model.getSnapshot();
		var camera = new OrbitCamera(snapshot.getBounds(), model.pose, view, target.getWidth(), target.getHeight());
		return rasterizer.draw(projector.project(snapshot, camera, rasterSize), TextureAnimation.currentCycle(), target);
	}

	public void drawIcon(@Nonnull PosedModel model, @Nonnull ItemRenderSheet.Row renderParams, float scale,
						 @Nonnull BufferedImage target)
	{
		var rasterSize = new RasterSize(target.getWidth(), target.getHeight(), ICON_SUPERSAMPLE);
		var snapshot = model.getSnapshot();
		var camera = new IconCamera(model.pose, renderParams, snapshot.getBounds().getHeight(), scale);
		rasterizer.drawOutlined(projector.project(snapshot, camera, rasterSize), TextureAnimation.currentCycle(), target);
	}
}

package io.huze.glamourer.render;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Getter;

/// A lit model snapshot from the client.
/// Can be drawn on any thread.
public final class ModelSnapshot
{
	public static final short UNTEXTURED = -1;
	/// The index of a face that draws from none of the glamour's colors or textures.
	public static final short NO_INDEX = -1;
	private static final int OPAQUE = 255;

	final float[] verticesX;
	final float[] verticesY;
	final float[] verticesZ;

	final int[] faceIndices1;
	final int[] faceIndices2;
	final int[] faceIndices3;
	/// Each vertex RGB or shade for textures.
	final int[] faceColors1;
	final int[] faceColors2;
	final int[] faceColors3;
	/// 0 for opaque up to 254, or null for a model with no transparent faces.
	@Nullable
	final byte[] faceTransparencies;
	/// Each face's texture or [#UNTEXTURED], or null for a model with no textured faces.
	@Nullable
	final short[] faceTextures;
	/// Each corner's place in the face's texture, as a share of its width and of its height. Null with faceTextures.
	@Nullable
	final float[] faceU1;
	@Nullable
	final float[] faceU2;
	@Nullable
	final float[] faceU3;
	@Nullable
	final float[] faceV1;
	@Nullable
	final float[] faceV2;
	@Nullable
	final float[] faceV3;
	/// The client's render priority of each face, or null for a model painted by depth alone.
	@Nullable
	final byte[] faceRenderPriorities;
	/// How far the client's GPU renderers nudge each face towards the camera, unsigned, so detail
	/// lying on a surface wins the depth test against it. Null for a model with no biased faces.
	@Nullable
	final byte[] faceBias;
	/// Which of a glamour's colors and textures each face draws from, by index, or null for a model
	/// read without a glamour.
	@Nullable
	final short[] faceColorIndices;
	@Nullable
	final short[] faceTextureIndices;
	/// Whether any face draws with a texture that scrolls, so a viewer knows to keep redrawing.
	@Getter
	private final boolean animated;

	@Getter
	@Nonnull
	private final ModelBounds bounds;

	@Builder
	private ModelSnapshot(@Nonnull float[] verticesX, @Nonnull float[] verticesY, @Nonnull float[] verticesZ,
						  @Nonnull int[] faceIndices1, @Nonnull int[] faceIndices2, @Nonnull int[] faceIndices3,
						  @Nonnull int[] faceColors1, @Nonnull int[] faceColors2, @Nonnull int[] faceColors3,
						  @Nullable byte[] faceTransparencies, @Nullable short[] faceTextures,
						  @Nullable float[] faceU1, @Nullable float[] faceU2, @Nullable float[] faceU3,
						  @Nullable float[] faceV1, @Nullable float[] faceV2, @Nullable float[] faceV3,
						  @Nullable byte[] faceRenderPriorities, @Nullable byte[] faceBias,
						  @Nullable short[] faceColorIndices, @Nullable short[] faceTextureIndices, boolean animated)
	{
		this.verticesX = verticesX;
		this.verticesY = verticesY;
		this.verticesZ = verticesZ;
		this.faceIndices1 = faceIndices1;
		this.faceIndices2 = faceIndices2;
		this.faceIndices3 = faceIndices3;
		this.faceColors1 = faceColors1;
		this.faceColors2 = faceColors2;
		this.faceColors3 = faceColors3;
		this.faceTransparencies = faceTransparencies;
		this.faceTextures = faceTextures;
		this.faceU1 = faceU1;
		this.faceU2 = faceU2;
		this.faceU3 = faceU3;
		this.faceV1 = faceV1;
		this.faceV2 = faceV2;
		this.faceV3 = faceV3;
		this.faceRenderPriorities = faceRenderPriorities;
		this.faceBias = faceBias;
		this.faceColorIndices = faceColorIndices;
		this.faceTextureIndices = faceTextureIndices;
		this.animated = animated;
		this.bounds = ModelBounds.of(verticesX, verticesY, verticesZ);
	}

	int getVertexCount()
	{
		return verticesX.length;
	}

	int getFaceCount()
	{
		return faceIndices1.length;
	}

	short getFaceTexture(int face)
	{
		return faceTextures == null ? UNTEXTURED : faceTextures[face];
	}

	int getFaceAlpha(int face)
	{
		return faceTransparencies == null ? OPAQUE : OPAQUE - (faceTransparencies[face] & 0xFF);
	}

	int getFaceBias(int face)
	{
		return faceBias == null ? 0 : faceBias[face] & 0xFF;
	}

	byte getFaceRenderPriority(int face)
	{
		return faceRenderPriorities == null ? 0 : faceRenderPriorities[face];
	}

	short getFaceColorIndex(int face)
	{
		return faceColorIndices == null ? NO_INDEX : faceColorIndices[face];
	}

	short getFaceTextureIndex(int face)
	{
		return faceTextureIndices == null ? NO_INDEX : faceTextureIndices[face];
	}
}

package io.huze.glamourer.render;

import javax.annotation.Nonnull;

final class OrbitCamera extends ModelCamera
{
	/// Per half viewport
	private static final double FOCAL_LENGTH = 512.0 / 18.0;
	private static final double FIT = 0.9;

	@Nonnull
	private final ViewTransform poseRotation;
	@Nonnull
	private final ViewTransform orbit;
	private final double distance;

	OrbitCamera(@Nonnull ModelBounds bounds, @Nonnull ModelPose pose, @Nonnull OrbitView view,
				int imageWidth, int imageHeight)
	{
		super(getPosed(bounds, pose).then(getOrbit(bounds, view)),
			Math.min(imageWidth, imageHeight) / 2.0 * FOCAL_LENGTH,
			imageWidth / 2.0 + view.getPanX(),
			imageHeight / 2.0 + view.getPanY());
		this.poseRotation = getPoseRotation(pose);
		this.orbit = getOrbit(bounds, view);
		this.distance = getDistance(bounds, view);
	}

	@Nonnull
	double[] toPosedOffset(double x, double y, double z)
	{
		return new double[]{
			poseRotation.toCameraX(x, y, z),
			poseRotation.toCameraY(x, y, z),
			poseRotation.toDepth(x, y, z)};
	}

	@Nonnull
	double[] projectModelOffset(double x, double y, double z)
	{
		double[] posed = toPosedOffset(x, y, z);
		double depth = orbit.toDepth(posed[0], posed[1], posed[2]);
		return new double[]{
			toImageX(orbit.toCameraX(posed[0], posed[1], posed[2]), depth),
			toImageY(orbit.toCameraY(posed[0], posed[1], posed[2]), depth),
			depth};
	}

	double getModelUnitsPerPixelAtCentre()
	{
		return distance / getFocalLength();
	}

	@Nonnull
	private static ViewTransform getPosed(@Nonnull ModelBounds bounds, @Nonnull ModelPose pose)
	{
		return ViewTransform.translation(-bounds.getCenterX(), -bounds.getCenterY(), -bounds.getCenterZ())
			.then(getPoseRotation(pose));
	}

	@Nonnull
	private static ViewTransform getPoseRotation(@Nonnull ModelPose pose)
	{
		return ViewTransform.roll(Math.sin(pose.getRoll()), Math.cos(pose.getRoll()))
			.then(ViewTransform.turn(Math.sin(pose.getTurn()), Math.cos(pose.getTurn())))
			.then(ViewTransform.tilt(Math.sin(pose.getTilt()), Math.cos(pose.getTilt())));
	}

	@Nonnull
	private static ViewTransform getOrbit(@Nonnull ModelBounds bounds, @Nonnull OrbitView view)
	{
		return view.orientation
			.then(ViewTransform.turn(Math.sin(view.getTurn()), Math.cos(view.getTurn())))
			.then(ViewTransform.tilt(Math.sin(view.getTilt()), Math.cos(view.getTilt())))
			.then(ViewTransform.translation(0, 0, getDistance(bounds, view)));
	}

	private static double getDistance(@Nonnull ModelBounds bounds, @Nonnull OrbitView view)
	{
		return bounds.getRadius() * FOCAL_LENGTH / FIT * view.getZoom();
	}
}

package io.huze.glamourer.render;

import java.util.List;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import lombok.Getter;

public final class OrbitGizmo
{
	public enum Ring
	{
		X,
		Y,
		Z,
		VIEW
	}

	private static final int POINTS_PER_RING = 64;
	/// Of the viewport's shorter side.
	private static final double RING_FRACTION = 0.3;
	private static final double VIEW_RING_EXTRA_PIXELS = 14;
	private static final double HIT_TOLERANCE_PIXELS = 7;
	private static final double TRIAL_ANGLE = 0.01;
	/// A ring squashed narrower than this is dragged along its line instead of round.
	private static final double EDGE_ON_RATIO = 0.15;

	public static final class RingShape
	{
		@Getter
		@Nonnull
		private final Ring ring;
		private final double[] xs;
		private final double[] ys;
		private final double[] depths;
		private final boolean[] behind;
		@Getter
		private final boolean edgeOn;
		private final double lineX;
		private final double lineY;

		private RingShape(@Nonnull Ring ring, double[] xs, double[] ys, double[] depths, double centreX, double centreY,
						  double centreDepth)
		{
			this.ring = ring;
			this.xs = xs;
			this.ys = ys;
			this.depths = depths;
			this.behind = new boolean[xs.length];
			double nearest = Double.MAX_VALUE;
			double furthest = 0;
			int furthestPoint = 0;
			for (int point = 0; point < xs.length; point++)
			{
				behind[point] = depths[point] > centreDepth;
				double radius = Math.hypot(xs[point] - centreX, ys[point] - centreY);
				nearest = Math.min(nearest, radius);
				if (radius > furthest)
				{
					furthest = radius;
					furthestPoint = point;
				}
			}
			this.edgeOn = nearest < furthest * EDGE_ON_RATIO;
			this.lineX = (xs[furthestPoint] - centreX) / furthest;
			this.lineY = (ys[furthestPoint] - centreY) / furthest;
		}

		private int getNearestToCamera()
		{
			int nearest = 0;
			for (int point = 1; point < depths.length; point++)
			{
				if (depths[point] < depths[nearest])
				{
					nearest = point;
				}
			}
			return nearest;
		}

		public int getPointCount()
		{
			return xs.length;
		}

		public double getX(int point)
		{
			return xs[point];
		}

		public double getY(int point)
		{
			return ys[point];
		}

		public boolean isBehind(int point)
		{
			return behind[point];
		}
	}

	@Nonnull
	private final PosedModel model;
	@Nonnull
	private final OrbitView view;
	private final int width;
	private final int height;
	@Nonnull
	private final OrbitCamera camera;
	private final double centreX;
	private final double centreY;
	private final double itemRadiusPixels;
	@Getter
	@Nonnull
	private final List<RingShape> rings;

	@Nonnull
	public static OrbitGizmo of(@Nonnull PosedModel model, @Nonnull OrbitView view, int width, int height)
	{
		return new OrbitGizmo(model, view, width, height);
	}

	private OrbitGizmo(@Nonnull PosedModel model, @Nonnull OrbitView view, int width, int height)
	{
		this.model = model;
		this.view = view;
		this.width = width;
		this.height = height;

		this.camera = new OrbitCamera(model.getSnapshot().getBounds(), model.pose, view, width, height);
		double[] centre = camera.projectModelOffset(0, 0, 0);
		this.centreX = centre[0];
		this.centreY = centre[1];
		this.itemRadiusPixels = RING_FRACTION * Math.min(width, height);
		double itemRadius = itemRadiusPixels * camera.getModelUnitsPerPixelAtCentre();
		this.rings = List.of(
			itemRing(Ring.X, itemRadius, centre[2]),
			itemRing(Ring.Y, itemRadius, centre[2]),
			itemRing(Ring.Z, itemRadius, centre[2]),
			viewRing(itemRadiusPixels + VIEW_RING_EXTRA_PIXELS));
	}

	@Nonnull
	private RingShape itemRing(@Nonnull Ring ring, double radius, double centreDepth)
	{
		double[] xs = new double[POINTS_PER_RING];
		double[] ys = new double[POINTS_PER_RING];
		double[] depths = new double[POINTS_PER_RING];
		for (int point = 0; point < POINTS_PER_RING; point++)
		{
			double along = radius * Math.cos(2 * Math.PI * point / POINTS_PER_RING);
			double across = radius * Math.sin(2 * Math.PI * point / POINTS_PER_RING);
			double[] projected;
			switch (ring)
			{
				case X:
					projected = camera.projectModelOffset(0, along, across);
					break;
				case Y:
					projected = camera.projectModelOffset(along, 0, across);
					break;
				default:
					projected = camera.projectModelOffset(along, across, 0);
					break;
			}
			xs[point] = projected[0];
			ys[point] = projected[1];
			depths[point] = projected[2];
		}
		return new RingShape(ring, xs, ys, depths, centreX, centreY, centreDepth);
	}

	@Nonnull
	private RingShape viewRing(double radius)
	{
		double[] xs = new double[POINTS_PER_RING];
		double[] ys = new double[POINTS_PER_RING];
		for (int point = 0; point < POINTS_PER_RING; point++)
		{
			xs[point] = centreX + radius * Math.cos(2 * Math.PI * point / POINTS_PER_RING);
			ys[point] = centreY + radius * Math.sin(2 * Math.PI * point / POINTS_PER_RING);
		}
		return new RingShape(Ring.VIEW, xs, ys, new double[POINTS_PER_RING], centreX, centreY, 0);
	}

	@Nullable
	public Ring hitTest(double x, double y)
	{
		Ring nearest = null;
		double nearestDistance = HIT_TOLERANCE_PIXELS;
		for (RingShape shape : rings)
		{
			double distance = distanceToRing(shape, x, y);
			if (distance < nearestDistance)
			{
				nearest = shape.ring;
				nearestDistance = distance;
			}
		}
		return nearest;
	}

	@Nonnull
	public Drag startDrag(@Nonnull Ring ring, double x, double y)
	{
		return new Drag(ring, x, y);
	}

	/// The cursor's angle about the centre becomes the turn. An edge on ring is pulled along its
	/// line instead, one radius per radian.
	public final class Drag
	{
		@Getter
		@Nonnull
		private final Ring ring;
		@Nonnull
		private final RingShape shape;
		/// Screen direction of a positive turn.
		private final double sign;
		private double lastX;
		private double lastY;

		private Drag(@Nonnull Ring ring, double x, double y)
		{
			this.ring = ring;
			this.shape = rings.get(ring.ordinal());
			this.lastX = x;
			this.lastY = y;
			this.sign = shape.edgeOn ? getRimSign(ring) : getScreenSign(ring, x, y);
		}

		@Nonnull
		public OrbitView dragTo(@Nonnull OrbitView current, double x, double y)
		{
			double turned = shape.edgeOn
				? ((x - lastX) * shape.lineX + (y - lastY) * shape.lineY) / itemRadiusPixels
				: normalize(angleAround(x, y) - angleAround(lastX, lastY));
			lastX = x;
			lastY = y;
			return rotate(current, ring, sign * turned);
		}
	}

	@Nonnull
	private OrbitView rotate(@Nonnull OrbitView view, @Nonnull Ring ring, double angle)
	{
		if (ring == Ring.VIEW)
		{
			return view.rotatedAboutViewAxis(angle);
		}
		double[] axis = camera.toPosedOffset(ring == Ring.X ? 1 : 0, ring == Ring.Y ? 1 : 0, ring == Ring.Z ? 1 : 0);
		return view.rotatedAboutPosedAxis(axis[0], axis[1], axis[2], angle);
	}

	private double getScreenSign(@Nonnull Ring ring, double x, double y)
	{
		Ring probe = ring == Ring.VIEW ? getOpenItemRing() : ring;
		RingShape shape = rings.get(probe.ordinal());
		int grabbed = nearestPoint(shape, x, y);
		double before = angleAround(shape.xs[grabbed], shape.ys[grabbed]);
		var nudged = new OrbitGizmo(model, rotate(view, ring, TRIAL_ANGLE), width, height);
		RingShape nudgedShape = nudged.rings.get(probe.ordinal());
		double after = nudged.angleAround(nudgedShape.xs[grabbed], nudgedShape.ys[grabbed]);
		return normalize(after - before) >= 0 ? 1 : -1;
	}

	private double getRimSign(@Nonnull Ring ring)
	{
		RingShape shape = rings.get(ring.ordinal());
		int near = shape.getNearestToCamera();
		var nudged = new OrbitGizmo(model, rotate(view, ring, TRIAL_ANGLE), width, height);
		RingShape nudgedShape = nudged.rings.get(ring.ordinal());
		double along = (nudgedShape.xs[near] - shape.xs[near]) * shape.lineX
			+ (nudgedShape.ys[near] - shape.ys[near]) * shape.lineY;
		return along >= 0 ? 1 : -1;
	}

	@Nonnull
	private Ring getOpenItemRing()
	{
		for (RingShape shape : rings)
		{
			if (shape.ring != Ring.VIEW && !shape.edgeOn)
			{
				return shape.ring;
			}
		}
		return Ring.Z;
	}

	private double angleAround(double x, double y)
	{
		return Math.atan2(y - centreY, x - centreX);
	}

	private static double normalize(double angle)
	{
		return Math.atan2(Math.sin(angle), Math.cos(angle));
	}

	private static int nearestPoint(@Nonnull RingShape shape, double x, double y)
	{
		int nearest = 0;
		double nearestDistance = Double.MAX_VALUE;
		for (int point = 0; point < shape.xs.length; point++)
		{
			double distance = Math.hypot(shape.xs[point] - x, shape.ys[point] - y);
			if (distance < nearestDistance)
			{
				nearest = point;
				nearestDistance = distance;
			}
		}
		return nearest;
	}

	private static double distanceToRing(@Nonnull RingShape shape, double x, double y)
	{
		double nearest = Double.MAX_VALUE;
		int count = shape.xs.length;
		for (int point = 0; point < count; point++)
		{
			int next = (point + 1) % count;
			nearest = Math.min(nearest, distanceToSegment(
				shape.xs[point], shape.ys[point], shape.xs[next], shape.ys[next], x, y));
		}
		return nearest;
	}

	private static double distanceToSegment(double x1, double y1, double x2, double y2, double x, double y)
	{
		double dx = x2 - x1;
		double dy = y2 - y1;
		double length = dx * dx + dy * dy;
		double along = length == 0 ? 0 : Math.max(0, Math.min(1, ((x - x1) * dx + (y - y1) * dy) / length));
		return Math.hypot(x - (x1 + along * dx), y - (y1 + along * dy));
	}
}

package io.huze.glamourer.render;

import javax.annotation.Nonnull;
import lombok.Getter;

public final class OrbitView
{
	public static final OrbitView INITIAL = new OrbitView(ViewTransform.IDENTITY, 0, 0, 1, 0, 0);

	@Nonnull
	final ViewTransform orientation;
	@Getter
	private final double turn;
	@Getter
	private final double tilt;
	@Getter
	private final double zoom;
	@Getter
	private final double panX;
	@Getter
	private final double panY;

	private OrbitView(@Nonnull ViewTransform orientation, double turn, double tilt, double zoom, double panX, double panY)
	{
		this.orientation = orientation;
		this.turn = turn;
		this.tilt = tilt;
		this.zoom = zoom;
		this.panX = panX;
		this.panY = panY;
	}

	@Nonnull
	public OrbitView turned(double byTurn, double byTilt)
	{
		return new OrbitView(orientation, turn + byTurn, tilt + byTilt, zoom, panX, panY);
	}

	@Nonnull
	public OrbitView rotatedAboutPosedAxis(double axisX, double axisY, double axisZ, double angle)
	{
		var rotation = ViewTransform.rotation(axisX, axisY, axisZ, angle);
		return new OrbitView(rotation.then(orientation), turn, tilt, zoom, panX, panY);
	}

	@Nonnull
	public OrbitView rotatedAboutViewAxis(double angle)
	{
		var turntableInverse = ViewTransform.tilt(-Math.sin(tilt), Math.cos(tilt))
			.then(ViewTransform.turn(-Math.sin(turn), Math.cos(turn)));
		var rotation = ViewTransform.rotation(
			turntableInverse.toCameraX(0, 0, 1), turntableInverse.toCameraY(0, 0, 1), turntableInverse.toDepth(0, 0, 1),
			angle);
		return new OrbitView(orientation.then(rotation), turn, tilt, zoom, panX, panY);
	}

	@Nonnull
	public OrbitView panned(double byX, double byY)
	{
		return new OrbitView(orientation, turn, tilt, zoom, panX + byX, panY + byY);
	}

	@Nonnull
	public OrbitView zoomedTo(double zoom)
	{
		return new OrbitView(orientation, turn, tilt, zoom, panX, panY);
	}
}

package io.huze.glamourer.render;

import javax.annotation.Nonnull;
import lombok.experimental.UtilityClass;

@UtilityClass
final class Outliner
{
	private static final int ICON_OUTLINE_ARGB = 0xFF000000;

	static void drawIconOutline(@Nonnull int[] raster, @Nonnull RasterSize size)
	{
		boolean[] isModel = new boolean[raster.length];
		for (int index = 0; index < isModel.length; index++)
		{
			isModel[index] = (raster[index] >>> 24) != 0;
		}
		paintEdge(raster, isModel, size, ICON_OUTLINE_ARGB);
	}

	static void paintEdge(@Nonnull int[] raster, @Nonnull boolean[] marked, @Nonnull RasterSize size, int argb)
	{
		final int width = size.getRasterWidth();
		final int height = size.getRasterHeight();
		final int reach = size.getSupersample();
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if (!marked[y * width + x] && isNear(marked, width, height, x, y, reach))
				{
					raster[y * width + x] = argb;
				}
			}
		}
	}

	private static boolean isNear(@Nonnull boolean[] marked, int width, int height, int x, int y, int reach)
	{
		for (int dy = -reach; dy <= reach; dy++)
		{
			int neighbourY = y + dy;
			if (neighbourY < 0 || neighbourY >= height)
			{
				continue;
			}
			for (int dx = -reach; dx <= reach; dx++)
			{
				int neighbourX = x + dx;
				if (neighbourX >= 0 && neighbourX < width && dx * dx + dy * dy <= reach * reach
					&& marked[neighbourY * width + neighbourX])
				{
					return true;
				}
			}
		}
		return false;
	}
}

