	public static void setIcon(@Nonnull JLabel label, @Nonnull BufferedImage image)
	{
		var dimension = new Dimension(image.getWidth(), image.getHeight());
		label.setPreferredSize(dimension);
		label.setMinimumSize(dimension);

		if (image instanceof AsyncBufferedImage)
		{
			// Each async image gets a unique generation. Stale async callbacks are skipped.
			final var generation = new Object();
			label.putClientProperty(ICON_GENERATION_KEY, generation);

			((AsyncBufferedImage) image).onLoaded(() ->
				SwingUtilities.invokeLater(() ->
				{
					if (label.getClientProperty(ICON_GENERATION_KEY) == generation)
					{
						label.setIcon(new ImageIcon(image));
					}
				}));
		}
		else
		{
			label.putClientProperty(ICON_GENERATION_KEY, null);
			label.setIcon(new ImageIcon(image));
		}
	}

	public static boolean shouldUseDarkForeground(Color color)
	{
		double luma = 0.299 * color.getRed() + 0.587 * color.getGreen() + 0.114 * color.getBlue();
		return luma >= 128;
	}

	private static ImageIcon loadImageIcon(String path)
	{
		return new ImageIcon(ImageUtil.loadImageResource(ImageIcons.class, path));
	}

	private static ImageIcon darkenImageIcon(ImageIcon icon)
	{
		Image img = icon.getImage();
		BufferedImage bi = new BufferedImage(
			img.getWidth(null), img.getHeight(null), BufferedImage.TYPE_INT_ARGB);

		Graphics g = bi.createGraphics();
		g.drawImage(img, 0, 0, null);
		g.dispose();

		RescaleOp op = new RescaleOp(0.8f, 0, null);
		bi = op.filter(bi, null);

		return new ImageIcon(bi);
	}

	private static ImageIcon tintImageIcon(ImageIcon icon, Color tint)
	{
		Image img = icon.getImage();
		int width = img.getWidth(null);
		int height = img.getHeight(null);
		BufferedImage bi = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);

		Graphics g = bi.createGraphics();
		g.drawImage(img, 0, 0, null);
		g.dispose();

		float tr = tint.getRed() / 255f;
		float tg = tint.getGreen() / 255f;
		float tb = tint.getBlue() / 255f;

		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int rgba = bi.getRGB(x, y);
				int a = (rgba >> 24) & 0xFF;
				int r = Math.round(((rgba >> 16) & 0xFF) * tr);
				int g2 = Math.round(((rgba >> 8) & 0xFF) * tg);
				int b = Math.round((rgba & 0xFF) * tb);
				bi.setRGB(x, y, (a << 24) | (r << 16) | (g2 << 8) | b);
			}
		}

		return new ImageIcon(bi);
	}

	private static ImageIcon invertImageIcon(ImageIcon icon)
	{
		Image img = icon.getImage();
		int width = img.getWidth(null);
		int height = img.getHeight(null);
		BufferedImage bi = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);

		Graphics g = bi.createGraphics();
		g.drawImage(img, 0, 0, null);
		g.dispose();

		// Invert RGB while preserving alpha
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int rgba = bi.getRGB(x, y);
				int a = (rgba >> 24) & 0xFF;
				int r = 255 - ((rgba >> 16) & 0xFF);
				int g2 = 255 - ((rgba >> 8) & 0xFF);
				int b = 255 - (rgba & 0xFF);
				bi.setRGB(x, y, (a << 24) | (r << 16) | (g2 << 8) | b);
			}
		}

		return new ImageIcon(bi);
	}
}

package io.huze.glamourer.ui;

import com.google.common.html.HtmlEscapers;
import java.util.concurrent.CompletableFuture;
import io.huze.glamourer.Config;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import io.huze.glamourer.texture.TextureImages;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.DataFlavor;
import javax.annotation.Nonnull;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

@Slf4j
public class ImportPlateDialog extends JDialog
{
	@Nonnull
	private final Config config;
	@Nonnull
	private final PlateManager plateManager;
	private final IconService iconService;
	@Nonnull
	private final TextureImages textureImages;

	private final JTextArea textArea;
	private final JPanel previewPanel;
	private final JLabel errorLabel;
	private final JLabel warningLabel;
	private final JButton importButton;
	private final JButton overwriteButton;

	private String jsonText;
	@Getter
	private boolean imported;
	@Getter
	private boolean overwritten;

	public ImportPlateDialog(@Nonnull Window owner,
							 @Nonnull Config config,
							 @Nonnull PlateManager plateManager,
							 @Nonnull TextureImages textureImages)
	{
		super(owner, "Import Plate", ModalityType.APPLICATION_MODAL);
		this.config = config;
		this.plateManager = plateManager;
		this.iconService = plateManager.getIconService();
		this.textureImages = textureImages;

		setLayout(new BorderLayout(0, 5));
		getRootPane().setBorder(new EmptyBorder(8, 8, 8, 8));
		getContentPane().setBackground(ColorScheme.DARKER_GRAY_COLOR);

		// Text area for pasting JSON
		textArea = new JTextArea(5, 40);
		textArea.setLineWrap(true);
		textArea.setWrapStyleWord(true);

		// Right-click paste menu
		JPopupMenu textAreaPopup = new JPopupMenu();
		JMenuItem pasteItem = new JMenuItem("Paste");
		pasteItem.addActionListener(e -> {
			try
			{
				String clipboard = (String) Toolkit.getDefaultToolkit()
					.getSystemClipboard().getData(DataFlavor.stringFlavor);
				textArea.replaceSelection(clipboard);
			}
			catch (Exception ex)
			{
				log.debug("Failed to paste from clipboard", ex);
			}
		});
		textAreaPopup.add(pasteItem);
		textArea.setComponentPopupMenu(textAreaPopup);

		JScrollPane textScroll = new JScrollPane(textArea);
		textScroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
		textScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

		JPanel topPanel = new JPanel(new BorderLayout());
		topPanel.setOpaque(false);
		JLabel pasteLabel = new JLabel("Paste plate JSON:");
		pasteLabel.setForeground(Color.WHITE);
		pasteLabel.setBorder(new EmptyBorder(0, 0, 4, 0));
		topPanel.add(pasteLabel, BorderLayout.NORTH);
		topPanel.add(textScroll, BorderLayout.CENTER);
		add(topPanel, BorderLayout.NORTH);

		// Preview panel (middle)
		JPanel centerPanel = new JPanel(new BorderLayout());
		centerPanel.setOpaque(false);

		VerticalScrollPane previewScroll = new VerticalScrollPane();
		previewPanel = previewScroll.getContainer();
		centerPanel.add(previewScroll, BorderLayout.CENTER);

		add(centerPanel, BorderLayout.CENTER);

		// Bottom panel: warning label + buttons
		JPanel bottomPanel = new JPanel(new BorderLayout());
		bottomPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bottomPanel.setBorder(new EmptyBorder(8, 0, 0, 0));

		warningLabel = new JLabel();
		warningLabel.setForeground(new Color(255, 170, 0));
		warningLabel.setBorder(new EmptyBorder(4, 4, 4, 0));
		warningLabel.setVisible(false);

		errorLabel = new JLabel();
		errorLabel.setForeground(new Color(255, 80, 80));
		errorLabel.setBorder(new EmptyBorder(4, 4, 4, 0));
		errorLabel.setVisible(false);

		JPanel messagePanel = new JPanel();
		messagePanel.setLayout(new BoxLayout(messagePanel, BoxLayout.Y_AXIS));
		messagePanel.setOpaque(false);
		messagePanel.add(warningLabel);
		messagePanel.add(errorLabel);
		bottomPanel.add(messagePanel, BorderLayout.NORTH);

		JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
		buttonPanel.setOpaque(false);

		overwriteButton = new JButton("Overwrite");
		overwriteButton.setVisible(false);
		overwriteButton.addActionListener(e -> doImport());

		importButton = new JButton("Import");
		importButton.setEnabled(false);
		importButton.addActionListener(e -> doImportAsNew());

		JButton cancelButton = new JButton("Cancel");
		cancelButton.addActionListener(e -> dispose());

		buttonPanel.add(overwriteButton);
		buttonPanel.add(importButton);
		buttonPanel.add(cancelButton);
		bottomPanel.add(buttonPanel, BorderLayout.CENTER);

		add(bottomPanel, BorderLayout.SOUTH);

		// Listen for text changes
		textArea.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				parseAndPreview();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				parseAndPreview();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				parseAndPreview();
			}
		});

		pack();
		setMinimumSize(new Dimension(350, 350));
		DialogUtil.positionNearCursor(this);
	}

	private void parseAndPreview()
	{
		String text = textArea.getText().trim();
		if (text.isEmpty())
		{
			clearPreview();
			return;
		}

		CompletableFuture<Plate> preview;
		try
		{
			preview = plateManager.loadImportPreview(text);
		}
		catch (Exception e)
		{
			showError(e.getMessage());
			return;
		}

		jsonText = text;
		importButton.setEnabled(false);
		errorLabel.setVisible(false);

		preview
			.thenAccept(plate -> SwingUtilities.invokeLater(() -> showPreview(plate)))
			.exceptionally(e -> {
				log.error("Failed to load plate for preview", e);
				SwingUtilities.invokeLater(() -> showError("Failed to load plate: " + e.getMessage()));
				return null;
			});
	}

	private void clearPreview()
	{
		jsonText = null;
		previewPanel.removeAll();
		previewPanel.setVisible(false);
		errorLabel.setVisible(false);
		warningLabel.setVisible(false);
		overwriteButton.setVisible(false);
		importButton.setEnabled(false);
	}

	private void showError(String message)
	{
		jsonText = null;
		previewPanel.removeAll();
		previewPanel.setVisible(false);
		warningLabel.setVisible(false);
		overwriteButton.setVisible(false);
		errorLabel.setText("<html>" + HtmlEscapers.htmlEscaper().escape(message) + "</html>");
		errorLabel.setVisible(true);
		importButton.setEnabled(false);
	}

	private void showPreview(Plate previewPlate)
	{
		errorLabel.setVisible(false);
		previewPanel.removeAll();

		PlateRowPanel rowPanel = new PlateRowPanel(previewPlate, iconService, config, textureImages, () -> {
			previewPanel.revalidate();
			previewPanel.repaint();
		});
		rowPanel.setExpanded(true);
		previewPanel.add(rowPanel);

		previewPanel.setVisible(true);

		int failedCount = previewPlate.getFailedGlamours().size();
		boolean duplicate = previewPlate.getId() != null && plateManager.hasPlateWithId(previewPlate.getId());

		StringBuilder warning = new StringBuilder("<html>");
		if (failedCount > 0)
		{
			warning.append(failedCount).append(" glamour").append(failedCount > 1 ? "s" : "")
				.append(" failed to load and is not shown.");
		}
		if (duplicate)
		{
			if (failedCount > 0)
			{
				warning.append("<br>");
			}
			warning.append("A plate with this ID already exists. Overwrite or import a new plate?");
		}
		warning.append("</html>");

		if (failedCount > 0 || duplicate)
		{
			warningLabel.setText(warning.toString());
			warningLabel.setVisible(true);
		}
		else
		{
			warningLabel.setVisible(false);
		}
		overwriteButton.setVisible(duplicate);
		overwriteButton.setEnabled(duplicate);

		importButton.setEnabled(true);
		previewPanel.revalidate();
		previewPanel.repaint();
		int maxHeight = (int) (Toolkit.getDefaultToolkit().getScreenSize().height * 0.90);
		getContentPane().setVisible(false);
		pack();
		if (getHeight() > maxHeight)
		{
			setSize(getWidth(), maxHeight);
		}
		getContentPane().setVisible(true);
	}

	private void doImport()
	{
		if (jsonText != null)
		{
			imported = true;
			overwritten = true;
			plateManager.importPlate(jsonText);
			dispose();
		}
	}

	private void doImportAsNew()
	{
		if (jsonText != null)
		{
			imported = true;
			plateManager.importPlateAsNew(jsonText);
			dispose();
		}
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.plate.Plate;
import java.awt.Color;
import java.awt.Insets;
import java.awt.datatransfer.DataFlavor;
import java.awt.dnd.DnDConstants;
import java.awt.dnd.DragGestureListener;
import java.awt.dnd.DragSource;
import java.awt.dnd.DropTarget;
import java.awt.dnd.DropTargetAdapter;
import java.awt.dnd.DropTargetDragEvent;
import java.awt.dnd.DropTargetDropEvent;
import java.awt.dnd.DropTargetEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import javax.swing.UIManager;

public class ItemDragDropHandler
{

	private static final Color DRAG_INDICATOR_COLOR = new Color(220, 138, 0);
	static final DataFlavor ITEM_FLAVOR = new DataFlavor(ItemData.class, "GlamourItem");

	public interface ItemMoveCallback
	{
		void moveItem(Plate sourcePlate, int sourceIndex, Plate targetPlate, int targetIndex);
	}

	/// Data transferred during item drag operations.
	public static class ItemData
	{
		public final Plate plate;
		public final int index;

		public ItemData(Plate plate, int index)
		{
			this.plate = plate;
			this.index = index;
		}
	}

	public static void setupItemDragAndDrop(JComponent component, Plate plate, int index,
											ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		setupDragSource(component, plate, index, onDragEnd);
		setupItemDropTarget(component, plate, index, moveCallback);
	}

	private static void setupDragSource(JComponent component, Plate plate, int index, Runnable onDragEnd)
	{
		Color originalBackground = component.getBackground();
		DragSource dragSource = DragSource.getDefaultDragSource();

		DragGestureListener listener = dge -> {
			if (DragDropUtil.isLeftButtonDrag(dge))
			{
				SingleFlavorTransferable<ItemData> transferable =
					new SingleFlavorTransferable<>(ITEM_FLAVOR, new ItemData(plate, index));
				DragDropUtil.startDrag(dge, transferable, component, originalBackground, onDragEnd);
			}
		};

		dragSource.createDefaultDragGestureRecognizer(component, DnDConstants.ACTION_MOVE, listener);
	}

	private static void setupItemDropTarget(JComponent component, Plate plate, int index,
											ItemMoveCallback moveCallback)
	{
		javax.swing.border.Border originalBorder = component.getBorder();
		Insets originalInsets = originalBorder != null ? originalBorder.getBorderInsets(component) : new Insets(0, 0, 0, 0);

		new DropTarget(component, DnDConstants.ACTION_MOVE, new DropTargetAdapter()
		{
			private boolean insertAfter = false;

			@Override
			public void dragOver(DropTargetDragEvent dtde)
			{
				ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
				if (data == null)
				{
					return;
				}

				dtde.acceptDrag(DnDConstants.ACTION_MOVE);
				insertAfter = calculateInsertPosition(dtde, data, plate, index, component);
				updateDragIndicator(component, data, plate, index, originalBorder, originalInsets, insertAfter);
			}

			@Override
			public void dragExit(DropTargetEvent dte)
			{
				component.setBorder(originalBorder);
			}

			@Override
			public void drop(DropTargetDropEvent dtde)
			{
				component.setBorder(originalBorder);
				handleItemDrop(dtde, plate, index, insertAfter, moveCallback);
			}
		}, true);
	}

	private static boolean calculateInsertPosition(DropTargetDragEvent dtde, ItemData data,
												   Plate plate, int index, JComponent component)
	{
		if (data.plate == plate)
		{
			return DragDropUtil.shouldInsertAfter(data.index, index);
		}
		else
		{
			return dtde.getLocation().y >= component.getHeight() / 2;
		}
	}

	private static void updateDragIndicator(JComponent component, ItemData data, Plate plate, int index,
											javax.swing.border.Border originalBorder, Insets originalInsets,
											boolean insertAfter)
	{
		if (data.plate == plate && data.index == index)
		{
			component.setBorder(originalBorder);
		}
		else
		{
			component.setBorder(DragDropUtil.createIndicatorBorder(originalInsets, !insertAfter, DRAG_INDICATOR_COLOR));
		}
	}

	private static void handleItemDrop(DropTargetDropEvent dtde, Plate plate, int index,
									   boolean insertAfter, ItemMoveCallback moveCallback)
	{
		ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
		if (data == null)
		{
			return;
		}

		if (data.plate == plate && data.index == index)
		{
			dtde.dropComplete(false);
			return;
		}

		dtde.acceptDrop(DnDConstants.ACTION_MOVE);
		int targetIndex = (data.plate == plate)
			? DragDropUtil.adjustTargetIndex(data.index, index, insertAfter)
			: (insertAfter ? index + 1 : index);

		moveCallback.moveItem(data.plate, data.index, plate, targetIndex);
		dtde.dropComplete(true);
	}

	public static void setupAddItemButtonDropTarget(JButton button, Plate plate,
													ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		String originalText = button.getText();

		new DropTarget(button, DnDConstants.ACTION_MOVE, new DropTargetAdapter()
		{
			private boolean isValidDrop = false;

			@Override
			public void dragOver(DropTargetDragEvent dtde)
			{
				ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
				isValidDrop = data != null && data.plate != plate;

				if (isValidDrop)
				{
					dtde.acceptDrag(DnDConstants.ACTION_MOVE);
					showDropZoneAppearance(button);
				}
			}

			@Override
			public void dragExit(DropTargetEvent dte)
			{
				revertButtonAppearance(button, originalText);
			}

			@Override
			public void drop(DropTargetDropEvent dtde)
			{
				revertButtonAppearance(button, originalText);
				handleButtonDrop(dtde, isValidDrop, plate, moveCallback, onDragEnd);
			}
		}, true);
	}

	private static void showDropZoneAppearance(JButton button)
	{
		button.setText("Drop Here");
		button.setBackground(new Color(
			DRAG_INDICATOR_COLOR.getRed(),
			DRAG_INDICATOR_COLOR.getGreen(),
			DRAG_INDICATOR_COLOR.getBlue(), 100));
		button.setBorder(BorderFactory.createLineBorder(DRAG_INDICATOR_COLOR, 2));
		button.setContentAreaFilled(true);
	}

	private static void revertButtonAppearance(JButton button, String originalText)
	{
		button.setText(originalText);
		button.setContentAreaFilled(false);
		button.setBorder(UIManager.getBorder("Button.border"));
	}

	private static void handleButtonDrop(DropTargetDropEvent dtde, boolean isValidDrop,
										 Plate plate, ItemMoveCallback moveCallback, Runnable onDragEnd)
	{
		ItemData data = DragDropUtil.getTransferData(dtde.getTransferable(), ITEM_FLAVOR, ItemData.class);
		if (!isValidDrop || data == null)
		{
			dtde.rejectDrop();
			return;
		}

		dtde.acceptDrop(DnDConstants.ACTION_MOVE);
		moveCallback.moveItem(data.plate, data.index, plate, plate.getGlamours().size());
		dtde.dropComplete(true);

		if (onDragEnd != null)
		{
			SwingUtilities.invokeLater(onDragEnd);
		}
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.ModelViewService;
import io.huze.glamourer.model.ModelChoice;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import io.huze.glamourer.render.ModelRenderer;
import io.huze.glamourer.render.OrbitView;
import io.huze.glamourer.texture.TextureImages;
import io.huze.glamourer.ui.colorpicker.ColorDisplay;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Window;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executor;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.ButtonGroup;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JSplitPane;
import javax.swing.JToggleButton;
import javax.swing.Timer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

public class ItemGlamourFrame extends JDialog
{
	private static final Dimension MINIMUM_SIZE = new Dimension(420, 300);
	private static final int MINIMUM_COLORS_WIDTH = 150;
	private static final int MINIMUM_MODEL_WIDTH = 160;
	private static final int DIVIDER_WIDTH = 6;
	private static final int FULL_SHADE = 100;
	private static final int SHADE_SLIDER_WIDTH = 80;
	/// Reads queue on the client thread, so a drag settles first.
	private static final int MODEL_SETTLE_MS = 120;
	private static final int LAYOUT_SETTLE_MS = 500;

	@Nonnull
	private final ModelViewService modelViewService;
	@Nonnull
	private final Config config;
	@Nonnull
	private final ConfigManager configManager;
	@Nonnull
	private final Plate plate;
	@Nonnull
	private final Glamour glamour;
	@Nonnull
	private final ModelViewPanel modelView;
	@Nonnull
	private final GlamourEditorPanel editor;
	private JSplitPane split;

	private JSlider shadeSlider;
	private final Timer modelSettleTimer = new Timer(MODEL_SETTLE_MS, event -> showModel());
	private final Timer layoutSettleTimer = new Timer(LAYOUT_SETTLE_MS, event -> saveLayout());
	private boolean mirroringLight;
	private final Runnable onLightChanged = () -> {
		mirroringLight = true;
		try
		{
			shadeSlider.setValue((int) Math.round(ColorDisplay.getLightIntensity() * FULL_SHADE));
		}
		finally
		{
			mirroringLight = false;
		}
		modelSettleTimer.restart();
	};

	private ModelChoice source = ModelChoice.ITEM;
	private int readGeneration;
	private final Map<ModelChoice, OrbitView> views = new HashMap<>();

	ItemGlamourFrame(@Nullable Window owner,
					 @Nonnull PlateManager plateManager,
					 @Nonnull Plate plate,
					 @Nonnull Glamour glamour,
					 @Nonnull ModelViewService modelViewService,
					 @Nonnull TextureImages textureImages,
					 @Nonnull Config config,
					 @Nonnull ConfigManager configManager,
					 @Nonnull Executor executor,
					 @Nonnull ModelRenderer modelRenderer,
					 @Nonnull Runnable onSettingsChanged,
					 @Nonnull Runnable onClosed)
	{
		super(owner, titleOf(glamour, plate), ModalityType.MODELESS);
		this.plate = plate;
		this.glamour = glamour;
		this.modelViewService = modelViewService;
		this.config = config;
		this.configManager = configManager;
		this.modelSettleTimer.setRepeats(false);
		this.layoutSettleTimer.setRepeats(false);

		this.modelView = new ModelViewPanel(executor, modelRenderer);
		this.editor = new GlamourEditorPanel(plate, glamour.getPrimaryItemId(), textureImages, config, false,
			modelSettleTimer::restart, modelView::setSelection);
		modelView.setOnPicked(editor::openPicker);
		modelView.setRowSelectionOf(editor::getRowSelection);

		setIconImages(ImageIcons.getWindowIcons());
		setDefaultCloseOperation(DISPOSE_ON_CLOSE);
		setMinimumSize(MINIMUM_SIZE);
		setSize(config.glamourWindowWidth(), config.glamourWindowHeight());
		setLocationRelativeTo(owner);

		var content = new JPanel(new BorderLayout());
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(createSplit(glamour, onSettingsChanged), BorderLayout.CENTER);
		setContentPane(content);
		UndoRedoKeys.install(getRootPane(), plateManager::undo, plateManager::redo);

		ColorDisplay.addLightIntensityListener(onLightChanged);
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent event)
			{
				layoutSettleTimer.restart();
			}
		});
		addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent event)
			{
				modelSettleTimer.stop();
				if (layoutSettleTimer.isRunning())
				{
					layoutSettleTimer.stop();
					saveLayout();
				}
				ColorDisplay.removeLightIntensityListener(onLightChanged);
				editor.dispose();
				onClosed.run();
			}
		});

		showModel();
	}

	@Nonnull
	private static String titleOf(@Nonnull Glamour glamour, @Nonnull Plate plate)
	{
		return glamour.getItemName() + " - " + plate.getName();
	}

	void refresh()
	{
		setTitle(titleOf(glamour, plate));
		editor.rebuild();
		showModel();
	}

	@Nonnull
	Plate getPlate()
	{
		return plate;
	}

	void rebuildColors()
	{
		editor.rebuild();
	}

	private void saveLayout()
	{
		configManager.setConfiguration(Config.GROUP, Config.KEY_GLAMOUR_WINDOW_WIDTH, getWidth());
		configManager.setConfiguration(Config.GROUP, Config.KEY_GLAMOUR_WINDOW_HEIGHT, getHeight());
		int colorsWidth = split.getRightComponent().getWidth();
		if (colorsWidth > 0)
		{
			configManager.setConfiguration(Config.GROUP, Config.KEY_GLAMOUR_WINDOW_COLORS_WIDTH, colorsWidth);
		}
	}

	private JSplitPane createSplit(@Nonnull Glamour glamour, @Nonnull Runnable onSettingsChanged)
	{
		var modelPane = createModelPane(glamour);
		modelPane.setMinimumSize(new Dimension(MINIMUM_MODEL_WIDTH, 0));

		split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, modelPane, createColorsPane(onSettingsChanged));
		split.setBorder(null);
		split.setDividerSize(DIVIDER_WIDTH);
		split.setContinuousLayout(true);
		split.setResizeWeight(1);
		split.setBackground(ColorScheme.DARK_GRAY_COLOR);
		split.addPropertyChangeListener(JSplitPane.DIVIDER_LOCATION_PROPERTY, event -> layoutSettleTimer.restart());
		return split;
	}

	private JPanel createModelPane(@Nonnull Glamour glamour)
	{
		var pane = new JPanel(new BorderLayout());
		pane.setBackground(ColorScheme.DARK_GRAY_COLOR);

		var sourceBar = createSourceBar(glamour);
		if (sourceBar != null)
		{
			pane.add(sourceBar, BorderLayout.NORTH);
		}
		pane.add(modelView, BorderLayout.CENTER);
		pane.add(createViewBar(), BorderLayout.SOUTH);
		return pane;
	}

	@Nullable
	private JPanel createSourceBar(@Nonnull Glamour glamour)
	{
		List<ModelChoice> choices = modelViewService.getChoices(glamour);
		if (choices.size() < 2)
		{
			return null;
		}
		boolean severalWorn = choices.stream().anyMatch(choice -> choice.getAlternatives() > 1);
		List<ModelChoice> inDropdown = severalWorn
			? choices.stream().filter(choice -> choice.getKind() != ModelChoice.Kind.PET).collect(Collectors.toList())
			: List.of();

		var bar = createBar();
		var group = new ButtonGroup();
		if (!inDropdown.isEmpty())
		{
			bar.add(createDropdown(inDropdown, group));
		}
		for (ModelChoice choice : choices)
		{
			if (!inDropdown.contains(choice))
			{
				bar.add(createToggle(choice, group));
			}
		}
		return bar;
	}

	@Nonnull
	private JToggleButton createToggle(@Nonnull ModelChoice choice, @Nonnull ButtonGroup group)
	{
		var button = new JToggleButton(choice.getLabel());
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setToolTipText(choice.getTooltip());
		button.setSelected(choice.equals(source));
		button.addActionListener(e -> showSource(choice));
		group.add(button);
		return button;
	}

	@Nonnull
	private JComboBox<ModelChoice> createDropdown(@Nonnull List<ModelChoice> choices, @Nonnull ButtonGroup group)
	{
		var dropdown = new JComboBox<>(choices.toArray(new ModelChoice[0]));
		dropdown.setFont(FontManager.getRunescapeSmallFont());
		dropdown.setToolTipText("Model to show");
		dropdown.addActionListener(e -> {
			group.clearSelection();
			showSource((ModelChoice) dropdown.getSelectedItem());
		});
		return dropdown;
	}

	private JPanel createViewBar()
	{
		var bar = createBar();

		var resetButton = new JButton("Reset view");
		resetButton.setFont(FontManager.getRunescapeSmallFont());
		resetButton.setToolTipText("Reset the view to defaults");
		resetButton.addActionListener(e -> modelView.resetView());
		bar.add(resetButton);

		var gizmoLabel = new JLabel("Gizmo");
		gizmoLabel.setFont(FontManager.getRunescapeSmallFont());
		gizmoLabel.setToolTipText("Toggle the rotation gizmo");
		bar.add(gizmoLabel);
		var gizmoToggle = new ToggleSwitch(config.glamourGizmo());
		modelView.setGizmoEnabled(gizmoToggle.isSelected());
		gizmoToggle.addItemListener(e -> {
			modelView.setGizmoEnabled(gizmoToggle.isSelected());
			configManager.setConfiguration(Config.GROUP, Config.KEY_GLAMOUR_GIZMO, gizmoToggle.isSelected());
		});
		bar.add(gizmoToggle);

		bar.add(createShadeSlider());
		return bar;
	}

	private static JPanel createBar()
	{
		var bar = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 4));
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return bar;
	}

	private JPanel createShadeSlider()
	{
		var panel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		panel.setOpaque(false);

		var label = new JLabel("Shade");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(label);

		shadeSlider = new JSlider(0, FULL_SHADE, (int) Math.round(ColorDisplay.getLightIntensity() * FULL_SHADE));
		shadeSlider.setOpaque(false);
		shadeSlider.setToolTipText("Shade intensity");
		shadeSlider.setPreferredSize(new Dimension(SHADE_SLIDER_WIDTH, shadeSlider.getPreferredSize().height));
		shadeSlider.addChangeListener(e -> {
			if (mirroringLight)
			{
				return;
			}
			ColorDisplay.setLightIntensity(shadeSlider.getValue() / (double) FULL_SHADE);
			if (!shadeSlider.getValueIsAdjusting())
			{
				configManager.setConfiguration(Config.GROUP, Config.KEY_SHADE_INTENSITY, shadeSlider.getValue());
			}
		});
		panel.add(shadeSlider);

		return panel;
	}

	private VerticalScrollPane createColorsPane(@Nonnull Runnable onSettingsChanged)
	{
		var scrollPane = new VerticalScrollPane();
		scrollPane.setPreferredSize(new Dimension(config.glamourWindowColorsWidth(), 0));
		scrollPane.setMinimumSize(new Dimension(MINIMUM_COLORS_WIDTH, 0));
		scrollPane.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

		var settings = new ThresholdSlidersPanel(config, onSettingsChanged);
		var container = scrollPane.getContainer();
		container.add(new CollapsiblePanel("Color group settings", ImageIcons.getSlidersIcon(), settings, false));
		editor.setAlignmentX(Component.LEFT_ALIGNMENT);
		container.add(editor);
		return scrollPane;
	}

	private void showSource(@Nonnull ModelChoice candidate)
	{
		views.put(source, modelView.getView());
		source = candidate;
		modelView.setView(views.getOrDefault(candidate, OrbitView.INITIAL));
		showModel();
	}

	private void showModel()
	{
		Glamour glamour = editor.getGlamour();
		if (glamour == null)
		{
			dispose();
			return;
		}

		final int generation = ++readGeneration;
		modelViewService.readModel(source, glamour, ColorDisplay.getLightIntensity(), model -> {
			if (generation == readGeneration)
			{
				modelView.setModel(model, model == null ? "No model" : "");
			}
		});
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.ModelViewService;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import io.huze.glamourer.render.ModelRenderer;
import io.huze.glamourer.texture.TextureImages;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;

@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class ItemGlamourWindows
{
	private final Client client;
	private final PlateManager plateManager;
	private final ModelViewService modelViewService;
	private final TextureImages textureImages;
	private final Config config;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;
	private final ModelRenderer modelRenderer;

	private final Map<String, ItemGlamourFrame> openFrames = new LinkedHashMap<>();

	public void open(@Nonnull Plate plate, @Nonnull Glamour glamour)
	{
		String key = keyOf(plate, glamour.getPrimaryItemId());
		var existing = openFrames.get(key);
		if (existing != null)
		{
			existing.refresh();
			existing.toFront();
			existing.requestFocus();
			return;
		}

		var clientWindow = SwingUtilities.getWindowAncestor(client.getCanvas());
		var frame = new ItemGlamourFrame(clientWindow, plateManager, plate, glamour, modelViewService, textureImages,
			config, configManager, executor, modelRenderer,
			this::rebuildColors,
			() -> openFrames.remove(key));
		openFrames.put(key, frame);
		frame.setVisible(true);
	}

	public void rebuildColors()
	{
		for (var frame : new ArrayList<>(openFrames.values()))
		{
			frame.rebuildColors();
		}
	}

	public void refreshAll()
	{
		var live = plateManager.getPlates();
		for (var frame : new ArrayList<>(openFrames.values()))
		{
			/// Close windows whose plate is no longer live.
			if (live.stream().noneMatch(plate -> plate == frame.getPlate()))
			{
				frame.dispose();
			}
			else
			{
				frame.refresh();
			}
		}
	}

	public void closeAll()
	{
		for (var frame : new ArrayList<>(openFrames.values()))
		{
			frame.dispose();
		}
		openFrames.clear();
	}

	@Nonnull
	private static String keyOf(@Nonnull Plate plate, int itemId)
	{
		return plate.getId() + ":" + itemId;
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.item.SearchService;
import io.huze.glamourer.party.PartyInterface;
import io.huze.glamourer.plate.Plate;
import io.huze.glamourer.plate.PlateManager;
import io.huze.glamourer.texture.TextureImages;
import java.awt.CardLayout;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.PluginPanel;

@Slf4j
public class MainPanel extends PluginPanel
{
	private static final String CARD_MAIN = "MAIN";
	private static final String CARD_SEARCH = "SEARCH";

	private final GlamourerPanel glamourerPanel;
	private final SearchPanel searchPanel;
	private final PlateManager plateManager;
	private final CardLayout cardLayout;

	private Plate currentSearchPlate;
	private int savedScrollPosition;

	@Inject
	public MainPanel(ClientThread clientThread, SearchService searchService, IconService iconService,
					 ScheduledExecutorService executor, Config config,
					 PlateManager plateManager, PartyInterface partyInterface,
					 ItemGlamourWindows itemWindows, TextureImages textureImages)
	{
		super(false);
		this.plateManager = plateManager;

		cardLayout = new CardLayout();
		setLayout(cardLayout);

		glamourerPanel = new GlamourerPanel(plateManager, partyInterface, config,
			this::showSearchPanelForPlate, itemWindows, textureImages);

		searchPanel = new SearchPanel(clientThread, searchService, iconService, executor,
			this::onItemSelectedFromSearch, this::hideSearchPanel);

		add(glamourerPanel, CARD_MAIN);
		add(searchPanel, CARD_SEARCH);

		cardLayout.show(this, CARD_MAIN);
	}

	public void showError(Exception ex)
	{
		glamourerPanel.showError(ex);
		cardLayout.show(this, CARD_MAIN);
	}

	@Override
	public void onActivate()
	{
		glamourerPanel.onActivate();
	}

	public void showSearchPanelForPlate(Plate plate)
	{
		currentSearchPlate = plate;

		savedScrollPosition = glamourerPanel.getPlateManagerPanel().getScrollPosition();

		PlateRowPanel rowPanel = glamourerPanel.getPlateManagerPanel().findRowPanelForPlate(plate);
		if (rowPanel != null)
		{
			rowPanel.ensureExpanded();
		}

		searchPanel.setExistingItemIds(plate.getItemIds());
		searchPanel.clearSearch();
		cardLayout.show(this, CARD_SEARCH);
		searchPanel.focusSearchBar();
	}

	public void hideSearchPanel()
	{
		searchPanel.clearResults();
		cardLayout.show(this, CARD_MAIN);
		glamourerPanel.getPlateManagerPanel().setScrollPosition(savedScrollPosition);
		revalidate();
		repaint();
		currentSearchPlate = null;
	}

	private void onItemSelectedFromSearch(int itemId)
	{
		if (currentSearchPlate == null)
		{
			log.warn("No plate being edited when item selected");
			return;
		}

		final Plate searchPlate = currentSearchPlate;
		plateManager.addGlamour(searchPlate, itemId).thenRun(() -> {
			SwingUtilities.invokeLater(() -> {
				PlateRowPanel rowPanel = glamourerPanel.getPlateManagerPanel().findRowPanelForPlate(searchPlate);
				if (rowPanel != null)
				{
					rowPanel.rebuildDetailsPanel();
					rowPanel.ensureExpanded();
				}
				hideSearchPanel();
			});
		});
	}
}

