	private static final int MOST_SUPERSAMPLED_PIXELS = 400_000;
	private static final Dimension MINIMUM_SIZE = new Dimension(120, 120);

	private static final float RING_WIDTH = 1.5f;
	private static final float ACTIVE_RING_WIDTH = 2.5f;
	private static final int RING_ALPHA = 200;
	private static final int BEHIND_RING_ALPHA = 70;
	private static final int ACTIVE_RING_ALPHA = 255;
	private static final Map<OrbitGizmo.Ring, Color> RING_COLORS = Map.of(
		OrbitGizmo.Ring.X, new Color(255, 0, 0),
		OrbitGizmo.Ring.Y, new Color(0, 255, 0),
		OrbitGizmo.Ring.Z, new Color(0, 0, 255),
		OrbitGizmo.Ring.VIEW, new Color(255, 255, 255));

	private final Executor executor;
	private final ModelRenderer renderer;

	@Nullable
	private PosedModel model;
	private String emptyMessage = "Loading model";
	@Nonnull
	private OrbitView view = OrbitView.INITIAL;

	@Nullable
	private Point dragOrigin;
	private boolean panning;
	private boolean hovering;
	private boolean gizmoEnabled;
	@Nullable
	private OrbitGizmo.Ring hoveredRing;
	@Nullable
	private OrbitGizmo.Drag gizmoDrag;

	@Setter
	@Nonnull
	private UnaryOperator<RegionSelection> rowSelectionOf = picked -> picked;
	@Setter
	@Nonnull
	private Consumer<RegionSelection> onPicked = picked -> {};
	@Nullable
	private RegionSelection selection;
	@Nullable
	private RegionSelection hoveredSelection;

	@Nullable
	private BufferedImage shown;
	@Nonnull
	private OrbitView shownView = OrbitView.INITIAL;
	@Nullable
	private ModelRegions shownRegions;
	@Nullable
	private BufferedImage spare;
	private boolean rendering;
	private boolean renderDue;

	@Nullable
	private BufferedImage outline;
	@Nullable
	private ModelRegions outlinedRegions;
	@Nullable
	private RegionSelection outlinedSelection;

	private final Timer animationTimer = new Timer(TextureAnimation.REDRAW_INTERVAL_MS, event -> requestRender());

	public ModelViewPanel(@Nonnull Executor executor, @Nonnull ModelRenderer renderer)
	{
		this.executor = executor;
		this.renderer = renderer;
		setMinimumSize(MINIMUM_SIZE);
		setPreferredSize(new Dimension(320, 320));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setCursor(getIdleCursor());

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent event)
			{
				var gizmo = getGizmo();
				var ring = gizmo == null || !SwingUtilities.isLeftMouseButton(event)
					? null
					: gizmo.hitTest(event.getX(), event.getY());
				if (ring != null)
				{
					gizmoDrag = gizmo.startDrag(ring, event.getX(), event.getY());
					return;
				}
				if (SwingUtilities.isLeftMouseButton(event))
				{
					return;
				}
				dragOrigin = event.getPoint();
				panning = SwingUtilities.isRightMouseButton(event);
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				dragOrigin = null;
				gizmoDrag = null;
				requestRender();
			}

			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (SwingUtilities.isLeftMouseButton(event) && hoveredSelection != null)
				{
					onPicked.accept(hoveredSelection);
				}
			}

			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovering = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovering = false;
				hoveredRing = null;
				hoveredSelection = null;
				repaint();
			}
		});

		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent event)
			{
				var gizmo = getGizmo();
				var ring = gizmo == null ? null : gizmo.hitTest(event.getX(), event.getY());
				if (ring != hoveredRing)
				{
					hoveredRing = ring;
					setCursor(ring == null ? getIdleCursor() : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
					repaint();
				}
				var under = ring != null ? null : getSelectionUnder(event.getX(), event.getY());
				if (!Objects.equals(under, hoveredSelection))
				{
					hoveredSelection = under;
					repaint();
				}
			}

			@Override
			public void mouseDragged(MouseEvent event)
			{
				if (gizmoDrag != null)
				{
					setView(gizmoDrag.dragTo(view, event.getX(), event.getY()));
					return;
				}
				if (dragOrigin == null)
				{
					return;
				}
				int dx = event.getX() - dragOrigin.x;
				int dy = event.getY() - dragOrigin.y;
				dragOrigin = event.getPoint();
				if (panning)
				{
					setView(view.panned(dx, dy));
				}
				else
				{
					turn(dx, dy);
				}
			}
		});

		addMouseWheelListener(event -> zoom(event.getWheelRotation()));

		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent event)
			{
				requestRender();
			}
		});
	}

	public void setModel(@Nullable PosedModel model, String emptyMessage)
	{
		this.model = model;
		this.emptyMessage = emptyMessage;
		updateAnimationTimer();
		requestRender();
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		updateAnimationTimer();
	}

	@Override
	public void removeNotify()
	{
		animationTimer.stop();
		super.removeNotify();
	}

	private void updateAnimationTimer()
	{
		if (model != null && model.getSnapshot().isAnimated() && isDisplayable())
		{
			animationTimer.start();
		}
		else
		{
			animationTimer.stop();
		}
	}

	@Nonnull
	public OrbitView getView()
	{
		return view;
	}

	public void setView(@Nonnull OrbitView view)
	{
		this.view = view;
		requestRender();
	}

	public void resetView()
	{
		setView(OrbitView.INITIAL);
	}

	public void setGizmoEnabled(boolean enabled)
	{
		gizmoEnabled = enabled;
		hoveredRing = null;
		setCursor(getIdleCursor());
		repaint();
	}

	public void setSelection(@Nullable RegionSelection selection)
	{
		this.selection = selection;
		repaint();
	}

	@Nonnull
	private Cursor getIdleCursor()
	{
		return Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR);
	}

	@Nullable
	private RegionSelection getSelectionUnder(int x, int y)
	{
		if (shownRegions == null)
		{
			return null;
		}
		int textureIndex = shownRegions.getTextureIndexAt(x, y);
		if (textureIndex != ModelRegions.NONE)
		{
			return rowSelectionOf.apply(RegionSelection.ofTexture(textureIndex));
		}
		int colorIndex = shownRegions.getColorIndexAt(x, y);
		return colorIndex == ModelRegions.NONE ? null : rowSelectionOf.apply(RegionSelection.ofColor(colorIndex));
	}

	private void turn(int dx, int dy)
	{
		double turnSign = Math.cos(view.getTilt()) >= 0 ? -1 : 1;
		double radiansPerPixel = getRadiansPerPixel();
		setView(view.turned(dx * radiansPerPixel * turnSign, dy * radiansPerPixel));
	}

	private double getRadiansPerPixel()
	{
		return 2 * Math.PI / Math.max(1, Math.min(getWidth(), getHeight()));
	}

	private void zoom(int notches)
	{
		double zoom = Math.max(CLOSEST_ZOOM,
			Math.min(FURTHEST_ZOOM, view.getZoom() * Math.pow(ZOOM_PER_NOTCH, notches)));
		setView(view.zoomedTo(zoom));
	}

	private void requestRender()
	{
		renderDue = true;
		if (!rendering)
		{
			startRender();
		}
	}

	private void startRender()
	{
		renderDue = false;
		final PosedModel model = this.model;
		final int width = getWidth();
		final int height = getHeight();
		if (model == null || width <= 0 || height <= 0)
		{
			repaint();
			return;
		}

		final int supersample = dragOrigin != null || gizmoDrag != null || width * height > MOST_SUPERSAMPLED_PIXELS
			? DRAG_SUPERSAMPLE
			: SUPERSAMPLE;
		final OrbitView view = this.view;
		final BufferedImage target = spare != null && spare.getWidth() == width && spare.getHeight() == height
			? spare
			: new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		spare = null;
		rendering = true;
		executor.execute(() -> {
			ModelRegions regions = null;
			try
			{
				regions = renderer.drawOrbit(model, view, supersample, target);
			}
			finally
			{
				final ModelRegions drawnRegions = regions;
				SwingUtilities.invokeLater(() -> {
					rendering = false;
					spare = shown;
					shown = target;
					shownView = view;
					shownRegions = drawnRegions;
					repaint();
					if (renderDue)
					{
						startRender();
					}
				});
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g;
		g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g2.fillRect(0, 0, getWidth(), getHeight());

		if (model == null)
		{
			paintMessage(g2);
			return;
		}
		if (shown != null)
		{
			g2.drawImage(shown, 0, 0, null);
		}
		var outlined = selection != null ? selection : hoveredSelection;
		if (outlined != null && shownRegions != null)
		{
			g2.drawImage(getOutline(shownRegions, outlined), 0, 0, null);
		}
		if (hovering || gizmoDrag != null)
		{
			paintGizmo(g2);
		}
	}

	@Nonnull
	private BufferedImage getOutline(@Nonnull ModelRegions regions, @Nonnull RegionSelection selection)
	{
		if (outline == null || regions != outlinedRegions || !selection.equals(outlinedSelection))
		{
			int width = shown == null ? getWidth() : shown.getWidth();
			int height = shown == null ? getHeight() : shown.getHeight();
			if (outline == null || outline.getWidth() != width || outline.getHeight() != height)
			{
				outline = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			}
			regions.outline(selection, outline);
			outlinedRegions = regions;
			outlinedSelection = selection;
		}
		return outline;
	}

	@Nullable
	private OrbitGizmo getGizmo()
	{
		if (!gizmoEnabled || model == null || shown == null)
		{
			return null;
		}
		return OrbitGizmo.of(model, shownView, shown.getWidth(), shown.getHeight());
	}

	private void paintGizmo(Graphics2D g2)
	{
		var gizmo = getGizmo();
		if (gizmo == null)
		{
			return;
		}
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		var active = gizmoDrag != null ? gizmoDrag.getRing() : hoveredRing;
		for (var shape : gizmo.getRings())
		{
			boolean isActive = shape.getRing() == active;
			g2.setStroke(new BasicStroke(isActive ? ACTIVE_RING_WIDTH : RING_WIDTH));
			var color = RING_COLORS.get(shape.getRing());
			int count = shape.getPointCount();
			for (int point = 0; point < count; point++)
			{
				int next = (point + 1) % count;
				boolean faint = shape.isBehind(point) && shape.isBehind(next);
				g2.setColor(withAlpha(color, isActive ? ACTIVE_RING_ALPHA : faint ? BEHIND_RING_ALPHA : RING_ALPHA));
				g2.draw(new Line2D.Double(shape.getX(point), shape.getY(point), shape.getX(next), shape.getY(next)));
			}
		}
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private void paintMessage(Graphics2D g2)
	{
		g2.setFont(new Font(FontManager.getRunescapeBoldFont().getName(), Font.PLAIN, 14));
		g2.setColor(ColorScheme.BRAND_ORANGE);
		FontMetrics metrics = g2.getFontMetrics();
		g2.drawString(emptyMessage,
			getWidth() / 2 - metrics.stringWidth(emptyMessage) / 2,
			getHeight() / 2 + metrics.getHeight() / 2);
	}
}

package io.huze.glamourer.ui;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum Ordering
{
	ALPHABETICAL("A to Z"),
	REVERSE_ALPHABETICAL("Z to A"),
	ITEM_ID("Item ID");

	final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
import io.huze.glamourer.glam.Glamour;
import io.huze.glamourer.glam.GlamourVisibility;
import io.huze.glamourer.glam.IconService;
import io.huze.glamourer.party.PartyInterface;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.PluginErrorPanel;

public class PartyPanel extends JPanel implements GlamourerSubPanel
{
	private final PartyInterface partyInterface;
	private final Config config;
	private final IconService iconService;
	private final Set<Long> expandedMembers = new HashSet<>();
	private final JPanel toolbarButtons;
	private final ToggleButton settingsToggleButton;
	private final JPanel settingsPanel;
	private final ToggleSwitch sendToggle;
	private final ToggleSwitch recvToggle;
	private final JPanel contentPanel;
	private final JPanel membersContainer;
	private final PluginErrorPanel infoPanel;

	public PartyPanel(PartyInterface partyInterface, Config config, IconService iconService)
	{
		this.partyInterface = partyInterface;
		this.config = config;
		this.iconService = iconService;

		setLayout(new BorderLayout());

		// --- Toolbar button: settings cog ---
		toolbarButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		toolbarButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton resyncButton = new JButton();
		ImageIcons.setSyncIcon(resyncButton);
		resyncButton.setToolTipText("Resync glamours with all party members");
		resyncButton.addActionListener(e -> partyInterface.resync());
		toolbarButtons.add(resyncButton);

		settingsToggleButton = new ToggleButton();
		ImageIcons.setCogIcon(settingsToggleButton);
		settingsToggleButton.setToolTipText("Settings");
		toolbarButtons.add(settingsToggleButton);

		// --- Settings sub-header (initially hidden) ---
		settingsPanel = new JPanel();
		settingsPanel.setLayout(new BoxLayout(settingsPanel, BoxLayout.Y_AXIS));
		settingsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		settingsPanel.setBorder(new EmptyBorder(6, 8, 6, 8));
		settingsPanel.setVisible(false);

		sendToggle = new ToggleSwitch(config.partySyncSend());
		settingsPanel.add(createToggleRow(Config.NAME_PARTY_SYNC_SEND,
			Config.DESC_PARTY_SYNC_SEND,
			sendToggle,
			config::setPartySyncSend));

		recvToggle = new ToggleSwitch(config.partySyncReceive());
		settingsPanel.add(createToggleRow(Config.NAME_PARTY_SYNC_RECV,
			Config.DESC_PARTY_SYNC_RECV,
			recvToggle,
			config::setPartySyncReceive));

		settingsToggleButton.addActionListener(e -> {
			boolean visible = !settingsPanel.isVisible();
			settingsPanel.setVisible(visible);
			settingsToggleButton.setActive(visible);
		});

		// --- Info panel for empty states ---
		infoPanel = new PluginErrorPanel();
		infoPanel.setVisible(false);

		// --- Content: members list ---
		contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBorder(new EmptyBorder(6, 6, 6, 6));

		JPanel membersSection = new JPanel(new BorderLayout());
		membersSection.setOpaque(false);

		JLabel membersLabel = new JLabel("Party Members");
		membersLabel.setForeground(Color.WHITE);
		membersLabel.setBorder(new EmptyBorder(0, 0, 4, 0));
		membersSection.add(membersLabel, BorderLayout.NORTH);

		membersContainer = new JPanel();
		membersContainer.setLayout(new BoxLayout(membersContainer, BoxLayout.Y_AXIS));
		membersContainer.setOpaque(false);
		membersSection.add(membersContainer, BorderLayout.CENTER);

		contentPanel.add(membersSection);

		JPanel centerPanel = new JPanel(new BorderLayout());
		centerPanel.add(infoPanel, BorderLayout.NORTH);
		VerticalScrollPane scrollPane = new VerticalScrollPane();
		scrollPane.getContainer().add(contentPanel);
		centerPanel.add(scrollPane, BorderLayout.CENTER);
		add(centerPanel, BorderLayout.CENTER);

		// Register for state changes
		partyInterface.setOnStateChanged(() -> SwingUtilities.invokeLater(this::rebuildMembers));

		rebuildMembers();
	}

	private JPanel createToggleRow(String label, String tooltip, ToggleSwitch toggle, Consumer<Boolean> onChange)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, 0, 2, 0));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

		JLabel nameLabel = new JLabel(label);
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setToolTipText(tooltip);
		row.add(nameLabel, BorderLayout.WEST);

		toggle.addItemListener(e -> onChange.accept(toggle.isSelected()));
		row.add(toggle, BorderLayout.EAST);

		return row;
	}

	@Override
	public String getCardKey()
	{
		return "PARTY";
	}

	@Override
	public JPanel getToolbarButtons()
	{
		return toolbarButtons;
	}

	@Nullable
	@Override
	public JPanel getSubHeaderPanel()
	{
		return settingsPanel;
	}

	@Override
	public void onActivate()
	{
		sendToggle.setSelected(config.partySyncSend());
		recvToggle.setSelected(config.partySyncReceive());
		if (!config.partySyncSend() && !config.partySyncReceive())
		{
			settingsPanel.setVisible(true);
			settingsToggleButton.setActive(true);
		}
		rebuildMembers();
	}

	public void rebuildMembers()
	{
		membersContainer.removeAll();

		if (!partyInterface.isPartyPluginActive())
		{
			infoPanel.setContent("Party plugin disabled", "Enable the Party plugin to use Party Sync.");
			infoPanel.setVisible(true);
			contentPanel.setVisible(false);
		}
		else if (!partyInterface.isInParty())
		{
			infoPanel.setContent("Not in a party", "Use the Party plugin to join a party.");
			infoPanel.setVisible(true);
			contentPanel.setVisible(false);
		}
		else
		{
			var members = partyInterface.getMembers();
			if (members.isEmpty())
			{
				infoPanel.setContent("Party empty", "Invite others to join to use Party Sync.");
				infoPanel.setVisible(true);
				contentPanel.setVisible(false);
			}
			else
			{
				infoPanel.setVisible(false);
				contentPanel.setVisible(true);
				for (var member : members)
				{
					membersContainer.add(createMemberRow(member));
				}
			}
		}

		membersContainer.revalidate();
		membersContainer.repaint();
	}

	private JPanel createMemberRow(PartyInterface.PartyMemberInfo member)
	{
		JPanel section = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(4, 4, 4, 4)
		));

		JPanel headerRow = new JPanel(new BorderLayout(2, 0));
		headerRow.setOpaque(false);

		final boolean expanded = expandedMembers.contains(member.memberId);
		JButton expandButton = new JButton();
		ImageIcons.setExpandIcon(expandButton, expanded);
		expandButton.addActionListener(e -> {
			if (!expandedMembers.remove(member.memberId))
			{
				expandedMembers.add(member.memberId);
			}
			rebuildMembers();
		});
		headerRow.add(expandButton, BorderLayout.WEST);

		JLabel nameLabel = new JLabel(member.displayName);
		nameLabel.setForeground(member.hasGlamourer ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		headerRow.add(nameLabel, BorderLayout.CENTER);

		{
			boolean hidden = partyInterface.isMemberHidden(member.memberId);
			boolean canToggle = member.hasGlamourer && member.hasName();

			JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
			rightPanel.setOpaque(false);

			GlamourVisibility visibility = !member.hasGlamourer ? GlamourVisibility.DISABLED
				: hidden ? GlamourVisibility.HIDDEN : GlamourVisibility.VISIBLE;
			JLabel eyeLabel = new JLabel(ImageIcons.getVisibilityIcon(visibility));
			eyeLabel.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
			rightPanel.add(eyeLabel);

			ToggleSwitch toggle = new ToggleSwitch(canToggle && !hidden);
			if (canToggle)
			{
				toggle.addItemListener(e -> {
					boolean nowHidden = !toggle.isSelected();
					partyInterface.setMemberHidden(member.memberId, nowHidden);
					eyeLabel.setIcon(ImageIcons.getVisibilityIcon(
						nowHidden ? GlamourVisibility.HIDDEN : GlamourVisibility.VISIBLE));
				});
			}
			else
			{
				toggle.setEnabled(false);
				toggle.setToolTipText(!member.hasName() ? "Not Logged In" : "Sync Disabled");
			}
			rightPanel.add(toggle);

			headerRow.add(rightPanel, BorderLayout.EAST);
		}

		section.add(headerRow, BorderLayout.NORTH);

		if (expanded)
		{
			section.add(createMemberGlamours(member.memberId), BorderLayout.CENTER);
		}

		return section;
	}

	/// The member's synced glamours, one read-only row each: the glamoured icon and the item name.
	private JPanel createMemberGlamours(long memberId)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		list.setBorder(new EmptyBorder(4, 4, 0, 0));

		var glamours = partyInterface.getMemberGlamours(memberId);
		if (glamours.isEmpty())
		{
			JLabel empty = new JLabel("No synced glamours");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			list.add(empty);
			return list;
		}

		for (Glamour glamour : glamours)
		{
			if (list.getComponentCount() > 0)
			{
				list.add(Box.createVerticalStrut(3));
			}

			JLabel itemName = new JLabel(glamour.getItemName());
			itemName.setForeground(Color.WHITE);

			JPanel row = new JPanel(new BorderLayout(5, 0));
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 3, 3, 3));

			JLabel icon = new JLabel();
			ImageIcons.setIcon(icon, iconService.getIcon(glamour));
			row.add(icon, BorderLayout.WEST);
			row.add(itemName, BorderLayout.CENTER);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			list.add(row);
		}
		return list;
	}

}

package io.huze.glamourer.ui;

import java.awt.Color;
import java.awt.Insets;
import java.awt.datatransfer.DataFlavor;
import java.awt.dnd.DnDConstants;
import java.awt.dnd.DragGestureListener;
import java.awt.dnd.DragSource;
import java.awt.dnd.DropTarget;
import java.awt.dnd.DropTargetAdapter;
import java.awt.dnd.DropTargetDragEvent;
import java.awt.dnd.DropTargetDropEvent;
import java.awt.dnd.DropTargetEvent;
import java.util.function.BiConsumer;
import javax.swing.JComponent;

public class PlateDragDropHandler
{
	private static final Color PLATE_DRAG_COLOR = new Color(50, 205, 50);
	static final DataFlavor PLATE_FLAVOR = new DataFlavor(Integer.class, "PlateIndex");

	public static void setupDragAndDrop(JComponent dragDropComponent, JComponent visualComponent, int index,
										BiConsumer<Integer, Integer> onReorder, Runnable onDragEnd)
	{
		final javax.swing.border.Border originalBorder = visualComponent.getBorder();
		final Color originalBackground = visualComponent.getBackground();
		final Insets originalInsets = originalBorder != null ? originalBorder.getBorderInsets(visualComponent) : new Insets(0, 0, 0, 0);

		DragSource dragSource = DragSource.getDefaultDragSource();

		DragGestureListener dragGestureListener = dge -> {
			if (DragDropUtil.isLeftButtonDrag(dge))
			{
				SingleFlavorTransferable<Integer> transferable = new SingleFlavorTransferable<>(PLATE_FLAVOR, index);
				DragDropUtil.startDrag(dge, transferable, visualComponent, originalBackground, onDragEnd);
			}
		};

		dragSource.createDefaultDragGestureRecognizer(dragDropComponent, DnDConstants.ACTION_MOVE, dragGestureListener);

		new DropTarget(dragDropComponent, DnDConstants.ACTION_MOVE, new DropTargetAdapter()
		{
			private boolean insertAfter = false;

			@Override
			public void dragOver(DropTargetDragEvent dtde)
			{
				Integer sourceIndex = DragDropUtil.getTransferData(dtde.getTransferable(), PLATE_FLAVOR, Integer.class);
				if (sourceIndex == null)
				{
					dtde.rejectDrag();
					return;
				}

				dtde.acceptDrag(DnDConstants.ACTION_MOVE);

				if (sourceIndex < index)
				{
					insertAfter = true;
					visualComponent.setBorder(DragDropUtil.createIndicatorBorder(originalInsets, false, PLATE_DRAG_COLOR));
				}
				else if (sourceIndex > index)
				{
					insertAfter = false;
					visualComponent.setBorder(DragDropUtil.createIndicatorBorder(originalInsets, true, PLATE_DRAG_COLOR));
				}
				else
				{
					visualComponent.setBorder(originalBorder);
				}
			}

			@Override
			public void dragExit(DropTargetEvent dte)
			{
				visualComponent.setBorder(originalBorder);
			}

			@Override
			public void drop(DropTargetDropEvent dtde)
			{
				visualComponent.setBorder(originalBorder);

				Integer fromIndex = DragDropUtil.getTransferData(dtde.getTransferable(), PLATE_FLAVOR, Integer.class);
				if (fromIndex == null || fromIndex == index)
				{
					dtde.rejectDrop();
					return;
				}

				dtde.acceptDrop(DnDConstants.ACTION_MOVE);
				int toIndex = DragDropUtil.adjustTargetIndex(fromIndex, index, insertAfter);
				onReorder.accept(fromIndex, toIndex);
				dtde.dropComplete(true);
			}
		}, true);
	}
}

package io.huze.glamourer.ui;

import io.huze.glamourer.Config;
