public class VerticalScrollPane extends JScrollPane
{
	public VerticalScrollPane()
	{
		super(new ScrollableContainer());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		getVerticalScrollBar().setPreferredSize(new Dimension(10, 0));
		setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
	}

	ScrollableContainer getContainer()
	{
		return (ScrollableContainer) getViewport().getView();
	}

	void scrollToTop()
	{
		getVerticalScrollBar().setValue(0);
	}

	void scrollToBottom()
	{
		var vertical = getVerticalScrollBar();
		vertical.setValue(vertical.getMaximum());
	}

	/// Scrollable wrapper forces content width to match the viewport, preventing clipping when the scrollbar appears
	public static class ScrollableContainer extends JPanel implements Scrollable
	{
		private ScrollableContainer()
		{
			setBackground(ColorScheme.DARK_GRAY_COLOR);
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

}

package io.huze.glamourer.ui.colorpicker;

import io.huze.glamourer.color.Brightness;
import io.huze.glamourer.color.Colors;
import io.huze.glamourer.color.Shade;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nonnull;
import lombok.Getter;

public final class ColorDisplay
{
	private static final int GRADIENT_STEPS = 21;
	private static final double FULL_LIGHT = 1;

	@Getter
	private static double lightIntensity = FULL_LIGHT;
	private static final List<Runnable> lightListeners = new ArrayList<>();

	private ColorDisplay()
	{
	}

	/// Swing thread only.
	public static void setLightIntensity(double intensity)
	{
		double clamped = Math.max(0, Math.min(FULL_LIGHT, intensity));
		if (clamped == lightIntensity)
		{
			return;
		}
		lightIntensity = clamped;
		for (var listener : new ArrayList<>(lightListeners))
		{
			listener.run();
		}
	}

	public static void addLightIntensityListener(@Nonnull Runnable listener)
	{
		lightListeners.add(listener);
	}

	public static void removeLightIntensityListener(@Nonnull Runnable listener)
	{
		lightListeners.remove(listener);
	}

	@Nonnull
	public static Color toColor(short hsl)
	{
		return brightened(Colors.hslToShadedColor(hsl, getMedianShade()));
	}

	@Nonnull
	public static Color toColor(int hue, int sat, int lum)
	{
		return brightened(Colors.hslToShadedColor(hue, sat, lum, getMedianShade()));
	}

	@Nonnull
	public static Color[] toColors(short hsl)
	{
		int darkest = getDarkestShade();
		int brightest = getBrightestShade();
		if (darkest == brightest)
		{
			return new Color[]{toColor(hsl)};
		}

		var colors = new Color[GRADIENT_STEPS];
		for (int i = 0; i < colors.length; i++)
		{
			int shade = darkest + (i * (brightest - darkest)) / (colors.length - 1);
			colors[i] = brightened(Colors.hslToShadedColor(hsl, shade));
		}
		return colors;
	}

	private static int getDarkestShade()
	{
		return Shade.fade(Shade.AMBIENT, lightIntensity);
	}

	private static int getBrightestShade()
	{
		return Shade.fade(Shade.BRIGHTEST, lightIntensity);
	}

	private static int getMedianShade()
	{
		return (getDarkestShade() + getBrightestShade()) / 2;
	}

	@Nonnull
	private static Color brightened(@Nonnull Color color)
	{
		return Brightness.getCurrent().applyBrightness(color);
	}
}

package io.huze.glamourer.ui.colorpicker;

import io.huze.glamourer.color.ColorReplacement;
import io.huze.glamourer.ui.DialogUtil;
import io.huze.glamourer.ui.Hoverable;
import io.huze.glamourer.ui.ImageIcons;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import lombok.Setter;

public abstract class ColorLabel extends JPanel implements Hoverable
{
	public static final int ROW_HEIGHT = 24;

	@Setter
	@Nonnull private Consumer<Short> onColorChange = x -> {};
	@Setter
	@Nonnull private Consumer<Short> onColorPreview = x -> {};
	@Setter
	@Nonnull private Runnable onHoverStart = () -> {};
	@Setter
	@Nonnull private Runnable onHoverEnd = () -> {};
	private final String pickerName;
	private final short originalHsl;
	protected final JLabel colorDisplay;
	protected final JButton revertButton;
	private JDialog activeDialog;
	private final Runnable onLightChanged = () -> {
		updateColorDisplay();
		repaint();
	};

	protected ColorLabel(String name, short originalHsl)
	{
		this.pickerName = name;
		this.originalHsl = originalHsl;

		setLayout(new BorderLayout(3, 0));
		setOpaque(false);

		// Main color display label (clickable to open picker)
		colorDisplay = new JLabel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				var replacementColors = getColorReplacements().stream()
					.map(r -> ColorDisplay.toColor(r.getReplacement()))
					.toArray(Color[]::new);
				ColorUtil.paintColorSpread(g, 0, 0, getWidth(), getHeight(), replacementColors);
				super.paintComponent(g);
			}
		};
		colorDisplay.setOpaque(false);
		colorDisplay.setBorder(new EmptyBorder(5, 5, 5, 5));
		colorDisplay.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		colorDisplay.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent mouseEvent)
			{
				showPicker();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				onHoverStart.run();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				onHoverEnd.run();
			}
		});
		add(colorDisplay, BorderLayout.CENTER);

		// Revert button (double-click to revert)
		revertButton = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				var originalColors = getColorReplacements().stream()
					.map(r -> ColorDisplay.toColor(r.getOriginal()))
					.toArray(Color[]::new);
				ColorUtil.paintColorSpread(g, 0, 0, getWidth(), getHeight(), originalColors);
				super.paintComponent(g);
			}

			@Override
			public Dimension getPreferredSize()
			{
				int rowHeight = ColorLabel.this.getHeight();
				int side = rowHeight > 0 ? rowHeight : colorDisplay.getPreferredSize().height;
				return new Dimension(side, side);
			}
		};
		revertButton.setToolTipText("Double-click to revert to original color");
		revertButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		revertButton.setBorderPainted(false);
		revertButton.setFocusPainted(false);
		revertButton.setContentAreaFilled(false);
		Color originalColor = ColorDisplay.toColor(originalHsl);
		revertButton.setBackground(originalColor);
		ImageIcons.setResetIcon(revertButton, originalColor);
		revertButton.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					revertToOriginal();
				}
			}
		});
		add(revertButton, BorderLayout.EAST);
	}

	protected void updateColorDisplay()
	{
		List<ColorReplacement> colors = getColorReplacements();
		short medianHsl = colors.get(colors.size() / 2).getReplacement();
		Color displayColor = ColorDisplay.toColor(medianHsl);
		colorDisplay.setBackground(displayColor);
		colorDisplay.setForeground(getContrastColor(displayColor));
		colorDisplay.setText(getDisplayText());

		boolean hasChanges = colors.stream().anyMatch(ColorReplacement::hasChanged);
		revertButton.setVisible(hasChanges);
		short medianOriginalHsl = colors.get(colors.size() / 2).getOriginal();
		ImageIcons.setResetIcon(revertButton, ColorDisplay.toColor(medianOriginalHsl));
		revertButton.repaint();
	}

	private static Color getContrastColor(Color color)
	{
		return ImageIcons.shouldUseDarkForeground(color) ? Color.BLACK : Color.WHITE;
	}

	protected void notifyColorChange(short newColor)
	{
		onColorChange.accept(newColor);
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		ColorDisplay.addLightIntensityListener(onLightChanged);
	}

	@Override
	public void removeNotify()
	{
		ColorDisplay.removeLightIntensityListener(onLightChanged);
		onHoverEnd.run();
		if (activeDialog != null)
		{
			activeDialog.dispose();
			activeDialog = null;
		}
		super.removeNotify();
	}

	public void setViewOnly()
	{
		colorDisplay.setCursor(Cursor.getDefaultCursor());
		revertButton.setCursor(Cursor.getDefaultCursor());
		revertButton.setToolTipText(null);
		revertButton.setIcon(null);
		revertButton.setRolloverIcon(null);
		for (var listener : colorDisplay.getMouseListeners()) {
			colorDisplay.removeMouseListener(listener);
		}
	}

	public void showPicker()
	{
		if (activeDialog != null && activeDialog.isVisible())
		{
			activeDialog.toFront();
			return;
		}

		final var initialColor = getPickerInitialColor();
		HslColorPicker picker = new HslColorPicker(originalHsl, initialColor);
		picker.setOnChange(onColorPreview);
		final AtomicBoolean okPressed = new AtomicBoolean();
		activeDialog = DialogUtil.showModelessDialogNearCursor(
			this,
			picker,
			pickerName,
			d -> {
				okPressed.set(true);
				if (picker.getColor() != initialColor)
				{
					onColorChanged(picker.getColor());
				}
			}
		);
		activeDialog.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				if (!okPressed.get() && picker.getColor() != initialColor)
				{
					onColorPreview.accept(initialColor);
				}
				activeDialog = null;
			}
		});
	}

	protected abstract List<ColorReplacement> getColorReplacements();

	protected abstract String getDisplayText();

	protected abstract void revertToOriginal();

	protected abstract void onColorChanged(short newColor);

	protected abstract short getPickerInitialColor();
}

package io.huze.glamourer.ui.colorpicker;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Rectangle;
import javax.swing.JSlider;
import javax.swing.plaf.basic.BasicSliderUI;
import lombok.Setter;

public class ColorSliderUI extends BasicSliderUI
{
	private static final int TRACK_HEIGHT = 10;
	private static final int THUMB_WIDTH = 3;

	@Setter
	private Color[] colors;

	public ColorSliderUI(JSlider b, Color[] colors)
	{
		super(b);
		this.colors = colors;
	}

	@Override
	public int xPositionForValue(int value)
	{
		double stepWidth = (double) trackRect.width / colors.length;
		return trackRect.x + (int) ((value + 0.5) * stepWidth);
	}

	@Override
	public int valueForXPosition(int xPos)
	{
		double stepWidth = (double) trackRect.width / colors.length;
		int value = (int) ((xPos - trackRect.x) / stepWidth);

		if (value < 0)
		{
			return 0;
		}
		if (value >= colors.length)
		{
			return colors.length - 1;
		}
		return value;
	}

	@Override
	public void paintThumb(Graphics g)
	{
		g.setColor(Color.WHITE);
		int x = thumbRect.x + (thumbRect.width / 2);
		g.fillRect(x - 1, thumbRect.y, THUMB_WIDTH, thumbRect.height);
		g.setColor(Color.BLACK);
		g.drawRect(x - 1, thumbRect.y, THUMB_WIDTH, thumbRect.height);
	}

	@Override
	public void paintTrack(Graphics g)
	{
		Rectangle t = trackRect;
		int trackY = t.y + (t.height / 2) - (TRACK_HEIGHT / 2);

		ColorUtil.paintColorSpread(g, t.x, trackY, t.width, TRACK_HEIGHT, colors);

		g.setColor(Color.DARK_GRAY);
		g.drawRect(t.x, trackY, t.width, TRACK_HEIGHT);
	}
}

package io.huze.glamourer.ui.colorpicker;

import java.awt.Color;
import java.awt.Graphics;
import lombok.experimental.UtilityClass;

@UtilityClass
class ColorUtil
{
	static void paintColorSpread(Graphics g, int x, int y, int width, int height, Color[] colors)
	{
		int count = colors.length;
		for (int i = 0; i < count; i++)
		{
			int xStart = i * width / count;
			int xEnd = (i + 1) * width / count;
			g.setColor(colors[i]);
			g.fillRect(x + xStart, y, xEnd - xStart, height);
		}
	}

	static void paintPreview(Graphics g, int width, int height, Color[] colors)
	{
		int steps = colors.length;
		if (steps == 1)
		{
			g.setColor(colors[0]);
			g.fillRect(0, 0, width, height);
			return;
		}

		int mid = steps / 2;
		int thirdW = width / 3;

		// Left third: dark gradient (darkest to median)
		for (int i = 0; i < mid; i++)
		{
			int idx = i;
			int xStart = i * thirdW / mid;
			int xEnd = (i + 1) * thirdW / mid;
			g.setColor(colors[idx]);
			g.fillRect(xStart, 0, xEnd - xStart, height);
		}

		// Middle third: median color
		g.setColor(colors[mid]);
		g.fillRect(thirdW, 0, width - 2 * thirdW, height);

		// Right third: light gradient (median to brightest)
		for (int i = 0; i < mid; i++)
		{
			int idx = mid + 1 + i;
			int xStart = width - thirdW + i * thirdW / mid;
			int xEnd = width - thirdW + (i + 1) * thirdW / mid;
			g.setColor(colors[idx]);
			g.fillRect(xStart, 0, xEnd - xStart, height);
		}
	}
}

